quests[58591] = { id = 58591, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plünderer", description = "Euer Vorgehen in Tirna Noch hat die Drust provoziert.\n\nDiese Kreaturen der Verrottung und Zerstörung strömen auf unsere Grenzen zu und haben schon begonnen, unsere Verteidigung zu durchbrechen.\n\nJetzt sehen wir ihre wahren Gesichter und erkennen, wer unser Feind ist.\n\nGreift sie an. Das wird uns etwas Zeit verschaffen, damit Ihr Traumwebers Ritual ausführen könnt.", sourceObjective = "Tötet Dörrhassdrust und Verseuchte, und vernichtet Skell den Plünderer.", completion = "Das ist erst der Anfang ihres Angriffs. Aber sie haben einen schweren Rückschlag erlitten. Ich danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[58592] = { id = 58592, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Betreuer betreuen", description = "Die Drust haben so schnell angegriffen... Sie haben einige der Geistpfleger dieses Hains gefangen genommen!\n\nEs ist keine einfache Aufgabe, zwischen der Dürre und den Monstern und allem. Ich weiß das.\n\nBitte versucht, sie aus der schrecklichen Magie zu befreien, die diese Eindringlinge gewirkt haben.", sourceObjective = "Befreit Geistpfleger im Traumschreinbecken.", completion = "Diese Drust sind wirklich grausam zu uns Fae! Die Geistpfleger haben nur versucht, ihre Arbeit zu machen...\n\nDanke, dass Ihr ihnen geholfen habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[58593] = { id = 58593, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ende des Traums", description = "Die Zeit ist reif. Das Ritual ist abgeschlossen, wenn Ihr die Träume des Geistes gänzlich betreten habt.\n\nEs wird in jeder Hinsicht so sein, als wärt Ihr ein und dieselbe Person.\n\nEr durchlebt den Augenblick seines Todes wieder und wieder. Es quält ihn. Etwas an seinem Ende, die Tatsache, dass er keine Kontrolle über seine Taten hatte und seine Liebsten verletzt hat.\n\nSprecht mit mir, wenn Ihr bereit seid, Euch in diesen Alptraum vom Ende zu begeben.", sourceObjective = "Erlebt das Ableben des Geistes mit.", completion = "Was für ein grässliches Ende für solch einen majestätischen Geist...\n\nAber deshalb hatte sie eine Verbindung zu Euch! Weil Ihr von derselben Welt stammt! Azeroth!\n\nJetzt spüre ich endlich, wie ihre Alpträume verblassen. Endlich erhält sie etwas Frieden.\n\nIch danke Euch mein Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[58595] = { id = 58595, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Säulen der Auslöschung", description = "In grauer Vorzeit haben die schwarzen Obelisken der Alten Götter die Ankunft ihrer Truppen angekündigt. Die dunklen Beschwörer der K'thir und N'raqi haben diese Monumente genutzt, um Brückenköpfe in unserer Welt zu erschaffen, über die weitere Diener N'Zoths herangebracht werden konnten.\n\nDie gleichen Obelisken finden sich jetzt überall auf den Schlachtfeldern. Solange sie stehen, wird die Flut an Truppen von N'Zoth niemals versiegen.\n\nReißt sie nieder.", sourceObjective = "Zerstört 6 Obelisken des Schwarzen Imperiums im Tal der Ewigen Blüten.", completion = "Ihr habt die Obelisken zerstört? Gut. Wir dürfen den Alten Göttern keinen Boden überlassen.\n\nVergesst das nicht bei Euren Schlachten.", sourceObjectiveStatus = "unverified-source-field" }
quests[58596] = { id = 58596, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gespenst des Krieges: Visektus" }
quests[58599] = { id = 58599, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grabt einen Graben zwischen ihnen", description = "Zuerst ruinieren wir ihre Operation. Für Fragen ist später noch Zeit.\n\nIch habe mir bei unserer Ankunft von der Warte aus einen Überblick verschafft. Totenbeschwörer laden Kristalle mit entzogener Anima auf. Drei Gräber stapeln sie auf Karren.\n\nTötet die Gräber, dann wird alles zum Erliegen kommen.", sourceObjective = "Tötet die 3 großen Gräber.", progress = "Seid Ihr bereit?", completion = "Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[58600] = { id = 58600, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein perfekter Reif", description = "Habe den perfekten Entwurf für Eure Zwecke: eine Krone, die die Energie der Ernter kanalisieren kann.\n\nIch brauche noch ein Werkzeug, um sie herzustellen. Eine Gussform. Es ist schwer, runde Objekte hinzubekommen.\n\nGeht in mein altes Lager. Dort ist eine perfekte Gussform. Da bin ich sicher.\n\nVielleicht in einer meiner alten Truhen. Durchsucht sie für mich, ja?", sourceObjective = "Sucht nach der perfektionierten Reifform.", progress = "Krone muss perfekt werden!", completion = "Perfekt gefertigt. Genau, was wir brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58601] = { id = 58601, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Netz der Informationen" }
quests[58603] = { id = 58603, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Phaestus, Genesis der Äonen", description = "Etwas Heiliges fehlt.\n\nVerschmähte haben unseren Schrein zu Ehren der Ersten Schmiedin geplündert und ihren Hammer gestohlen. Meinen Hammer!\n\nBesiegt ihren Kommandanten und holt Phaestus zurück. Geht! Sofort!", sourceObjective = "Holt Phaestus, Genesis der Äonen, von Aufseher Atticus zurück.", progress = "Ohne Phaestus können wir Eure Krone nicht schmieden!", completion = "Phaestus ist zurück! Was für ein Tag.\n\nVielen Dank. Seit Äonen reichen wir diesen Hammer an unsere Nachfolger weiter! Sein Platz ist hier, in meinen meisterlichen Händen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58605] = { id = 58605, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amateurabend" }
quests[58606] = { id = 58606, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teilchenforschung", sourceObjective = "Sammelt 16 Aqirteilchen.", progress = "Konntet Ihr die Proben beschaffen?", completion = "Hervorragend! Euer Beitrag zur Arbeit der Liga wird gewürdigt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[58608] = { id = 58608, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dann also Verrat", description = "Wir haben ihnen Sand ins Getriebe gestreut, doch es gibt noch mehr zu tun.\n\nSin'dane muss jemanden geschickt haben, der das Lager überwacht.\n\nFindet und tötet denjenigen, der die Verantwortung hat. Nur dann können wir sicher sein, dass ihre Arbeit vorbei ist.", sourceObjective = "Tötet Lady Ouix'Ara.", progress = "Noch mehr Pläne...", completion = "Der Verbannte... Die Schulterstücke des Imperiums...\n\nDieser Lich, Kel'Thuzad, hat sich mit mächtigen Kräften eingelassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58609] = { id = 58609, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Sitz einnehmen", description = "Eine weise Entscheidung, {name}. Unter Eurem Kommando werden wir Maldraxxus wieder zu alter Größe führen.\n\nEure Stärke kann die Schattenlande zum Besseren wandeln. Nur mit den Nekrolords erreicht Ihr Euer volles Potenzial.\n\nMacht Euch fürs Erste auf zum Sitz des Primus. Baronin Draka trifft Euch dort und wird Euch weiter anleiten.", sourceObjective = "Meldet Euch bei Baronin Draka im Sitz des Primus in Maldraxxus.", completion = "Willkommen zurück zum Kampf, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[58610] = { id = 58610, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elunes Sprecher", description = "Das Glück ist uns hold, {name}. Wir haben im Ardenwald eine Seele gefunden, die einst zu Lebzeiten ein Nachtkrieger war, so wie Tyrande jetzt.\n\nSein Name ist Thiernax. Mir wurde gesagt, dass er sich um die Geister kümmert, die im Garten der Nacht ruhen.\n\nSucht ihn auf und bittet ihn um Hilfe. Ich bete, dass er über Weisheit verfügt, die er an uns weitergeben kann.", sourceObjective = "Findet Thiernax beim Garten der Königin.", progress = "Oh je.", completion = "<Qadarin beobachtet, wie Thiernax davonstürmt. Er seufzt und wendet sich Euch zu.>\n\nVerzeiht. Thiernax mag vielleicht schroff gewirkt haben, aber es gibt einen Grund für seine Zurückhaltung, über den Nachtkrieger zu sprechen.\n\nWenn Ihr mir kurz im Garten zur Hand geht, kann ich das näher ausführen. Dann werde ich sehen, wie Thiernax davon überzeugt werden kann, Eurer Mutter zu helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58615] = { id = 58615, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stimmen in der Dunkelheit", description = "Habt Ihr das auch gehört? Das kann nichts Gutes bedeuten.\n\nWenn N'Zoth in diese Kammer gelangt, ist es um uns geschehen!\n\nWir müssen herausfinden, wo er Zutritt zur Kammer hat, und dem einen Riegel vorschieben, bevor er zu mehr in der Lage ist, als uns nur etwas zuzuflüstern.", sourceObjective = "Findet die Quelle von N'Zoths Flüstern in der Herzkammer.", completion = "Was haben wir getan?\n\nOhne Ra-dens Opfer hätte N'Zoth die Kammer übernommen und Azeroth wäre leichte Beute für ihn gewesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58616] = { id = 58616, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einen Champion schmieden", description = "Von allen Seelen, die diesen Stein erreicht haben, habt nur Ihr seine wahre Bestimmung erkannt.\n\nIch bin kein Fanatiker, aber dies hat eine tiefere Bedeutung. Es wäre weise, weiter nachzuforschen.\n\nBesucht Knochenschmiedin Heirmir in ihrer Schmiede. Sie ist die renommierteste Schmiedin in Maldraxxus und der letzte verbliebene Lehrling des Primus.\n\nSie wird wissen, welcher Weg einzuschlagen ist.", sourceObjective = "Sprecht mit Knochenschmiedin Heirmir über Eure Runenklinge.", progress = "Noch etwas?", completion = "Das wird einiges an Arbeit erfordern.", sourceObjectiveStatus = "unverified-source-field" }
quests[58617] = { id = 58617, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ordnung wahren", description = "Kommunikation ist der Schlüssel zum Sieg. Die größten Strategen sind nutzlos, wenn niemand ihre Befehle befolgt.\n\nÜberbringt Beschwörer Perex, Ausbildungsoffizierin Telice und Secutor Mevix meine Befehle.\n\nUnd seid schnell. Jeder Moment, den wir verschwenden, kann vom Feind zu dessen Vorteil genutzt werden!", sourceObjective = "Überbringt Beschwörer Perex, Ausbildungsoffizierin Telice und Secutor Mevix Befehle.", completion = "Das sollte sicherstellen, dass wir für den Krieg bereit sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[58618] = { id = 58618, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Osseinverzauberung", description = "Eine mächtige Klinge braucht mächtige Bestandteile. Ich kenne da etwas, das zu Euren Bedürfnissen passen würde.\n\nKürzlich haben unsere Soldaten eine Monstrosität an der Ostseite unserer Hochburg eingefangen, die von den Konstrukten ausgebildet wurde. Vyraz ist sich sicher, dass wir dem Verstand der Bestie \"Intelligenz\" entziehen können.\n\nHmpf. Der Wille eines Primus schlägt die Wünsche eines ambitionierten Barons!\n\nDie Knochen der Bestie würden einen idealen Griff für diese Klinge abgeben. Ihr solltet sie nehmen.", sourceObjective = "Tötet Markkiefer und sammelt einen ermächtigten Knochen von seinem Leichnam.", progress = "Mutig genug, das zu erledigen?", completion = "Gut! Ich wusste, dass diese Bestie keine Herausforderung für Euch darstellt.", sourceObjectiveStatus = "unverified-source-field" }
quests[58619] = { id = 58619, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwischen den Zeilen lesen", description = "Ah, <Sterblicher/Sterbliche>, was für ein Glück, dass ich, der demütige Ta'eran, zufällig hier stehe, während Ihr, der Fremdling, der in aller Munde ist, zufällig vorbeikommt.\n\nEs gibt eine Angelegenheit, die ich im Geiste der Zusammenarbeit und der gegenseitigen Interessen gerne besprechen möchte.\n\nEin nahe gelegenes Bauwerk, das Grabmal des Wissens, wurde als Aufbewahrungsort für militärische Strategien erbaut. Ich fürchte, das darin enthaltene Wissen könnte bald verloren gehen.\n\nWenn Ihr mir die Ehre erweist, mich zum Grabmal zu begleiten, kann ich Euch mitteilen, was ich sonst noch weiß.", sourceObjective = "Folgt Ta'eran zum Grabmal des Wissens und hört Euch seinen Vorschlag an.", completion = "Sterblicher, seid Ihr bereit, mir zu helfen, diese wertvollen Schriften zu retten?", sourceObjectiveStatus = "unverified-source-field" }
quests[58620] = { id = 58620, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todeslinien", description = "Zugang zum Grabmal zu erlangen ist keine leichte Aufgabe, {name}!\n\nNicht nur wurden Wächter postiert, sondern es wurde auch ein aufwendiges magisches Schloss geschaffen, um die Tür zu versiegeln.\n\nUm den Weg freizumachen, müssen die beiden Obelisken, die das Schloss kontrollieren, mit Anima versorgt werden. Glücklicherweise gibt es in dem Bereich einige ermächtigte Kristalle, die wir zu diesem Zweck nutzen können.\n\nFindet die Fokuskristalle und leitet ihren Animafluss in die Obelisken um. Dann werden die Geheimnisse des Grabmals bald uns gehören!", sourceObjective = "Verbindet den Animafluss mit den Entriegelungsobelisken.", progress = "Habt Ihr die beiden Obelisken aktiviert?", completion = "Ihr habt es geschafft! Die Tür ist entriegelt!", sourceObjectiveStatus = "unverified-source-field" }
quests[58621] = { id = 58621, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprecht mir nach", description = "Der Primus stellte Wächter in der Gegend um das Grabmal auf, um das darin enthaltene Wissen zu schützen. Jeder verkörperte die Tugenden eines der fünf Häuser.\n\nUm Zutritt zu erhalten, muss man sich als würdig erweisen, indem man diese Beschützer besiegt.\n\nSucht die Runensteine, die die Häuser von Maldraxxus repräsentieren. Achtet auf die Worte, die auf jedem Stein eingraviert sind, und zollt dann den Werten der einzelnen Häuser Ehre.\n\nWenn Ihr den Stein ehrt, wird sein Beschützer sich zeigen. Besiegt sie alle.", sourceObjective = "Lest die Runensteine der fünf Häuser und ehrt sie dann, indem Ihr vor jedem Stein das richtige /emote ausführt.", completion = "Jetzt, da wir diese Wächter losgeworden sind, können wir uns darauf konzentrieren, die Tür aufzuschließen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58622] = { id = 58622, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse in den Regalen", description = "Die Tür zum Grabmal ist aufgeschlossen und wir können uns hineinwagen.\n\nUnd mit \"wir\" meine ich \"Ihr\". Zumindest bis es sicher ist.\n\nDie Bände im Inneren enthalten die gesammelte Weisheit der größten militärischen Köpfe von Maldraxxus. Tut zum Wohle der Nekrolords alles, was nötig ist, um diese wertvollen Bände zu sammeln.\n\nMan kann sicher davon ausgehen, dass die Bücher durch Fallen geschützt sind. Der Primus würde nicht wollen, dass einfach irgendjemand Hand an dieses Wissen legt.\n\nSobald Ihr einen Weg freimacht, schließe ich mich Euch an.", sourceObjective = "Bergt Bände der Folianten, die im Grabmal aufbewahrt werden.", completion = "Gute Arbeit bisher.\n\nWir stehen kurz vor dem Zugriff auf die geheimen Archive!", sourceObjectiveStatus = "unverified-source-field" }
quests[58623] = { id = 58623, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein ganzes Set", description = "Das ist nur der erste Band?\n\nWir können nicht nur den ersten Band nehmen. So ein seltenes Stück besitzt nur als ganzes Set Wert!\n\nNehmt so viele Bände, wie Ihr könnt. Ich muss eine größere Operation vorbereiten, um alle Bände zu holen.", sourceObjective = "Sammelt Schriften des Sieges.", progress = "Haben wir alle Exemplare?", completion = "Wir haben so viel wertvolles Wissen gerettet, und ohne Euch hätte ich das nicht geschafft.", sourceObjectiveStatus = "unverified-source-field" }
quests[58624] = { id = 58624, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schulterstücke des Imperiums", description = "Jetzt wissen wir, wer für die Unruhen in Maldraxxus verantwortlich ist.\n\nWenn Kel'Thuzad mit dem Verbannten eine Allianz gebildet hat, dann besitzt er größere Macht, als gedacht. \n\nWir brauchen Zeit für Vorbereitungen und müssen dann das Haus der Rituale belagern, denn ohne einen perfekten Angriffsplan werden wir scheitern.\n\nBringt zuerst die Schulterstücke zum Sitz des Primus. Ich treffe Euch dort.", sourceObjective = "Kehrt zum Sitz des Primus mit den Schulterstücken des Imperiums zurück.", completion = "Der Kampf hat erst begonnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58625] = { id = 58625, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eins und eins zusammenzählen", description = "Der alte Baron des Hauses der Auserwählten? Ah ja! Ich erinnere mich, ihn gesehen zu haben! Ein zorniger Geist, aber ein hervorragender Kämpfer.\n\nEr wollte sich mit jemandem aus dem Haus der Rituale treffen. Er hat einige seiner Wachen mitgenommen.\n\nEs ist schon etwas her, dass er hier entlang kam, aber Ihr solltet Spuren finden, wo er in Richtung des alten Fußpfads in die Berge unterwegs war.", sourceObjective = "Sucht die Vergessenen Wunden nach dem alten Baron ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[58630] = { id = 58630, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krone der Ernter", description = "Macht, die Ihr fokussieren wollt, ist unbeständig. Brauchen die Flammen der Ewigen Schmiede, um das zu schaffen.\n\nIch fürchte, ohne den Segen der Flammen wird sie den Träger überwältigen.\n\nBringt Venthyrfreund. Seine Magie wird nützlich sein. Brauche Euch, um Unreinheiten zu absorbieren.\n\n<Mikanikos gibt Euch einen eleganten Behälter.>\n\nBenutzt ihn, um Unvollkommenheiten einzufangen, die während des Prozesses wegbrennen.", sourceObjective = "Trefft Mikanikos an der Ewigen Schmiede. Helft ihm dann, die Krone der Ernter zu schmieden.", progress = "Ist es vollbracht?", completion = "Perfektion.", sourceObjectiveStatus = "unverified-source-field" }
quests[58631] = { id = 58631, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinein in die Träume", description = "Ich kann nicht glauben, dass Ra-den sich für unsere Rettung geopfert hat. Wir dürfen ihn nicht einfach aufgeben!\n\nEs muss doch einen Weg geben, herauszufinden, wohin er verschwunden ist.\n\nLasst uns mal sehen, ob MUTTER ihn aufspüren kann!", sourceObjective = "Sprecht mit MUTTER in der Herzkammer, um Ra-den aufzuspüren.", progress = "Uns läuft die Zeit davon!", completion = "Das Portal muss der Eingang zu N'Zoths Reich sein.\n\nDies könnte unsere einzige Chance sein, Ra-den zurückzubekommen und N'Zoth endgültig zur Strecke zu bringen!", sourceObjectiveStatus = "unverified-source-field" }
quests[58632] = { id = 58632, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ny'alotha, die Erwachte Stadt: Das Ende des Verderbers", description = "Mithilfe der Moguforschung haben MUTTER und Ra-den eine Möglichkeit gefunden, das Ursprungsprotokoll der Schmiede durch die Herzkammer hindurch zu fokussieren. Das einzige Problem war, herauszufinden, wohin man den Schuss lenken muss.\n\nDas ist jetzt gelöst.\n\nNehmt diese Anker und geht durch das Portal. Ihr müsst einige markante Orientierungspunkte finden und sie dort aufstellen, damit wir die Waffe fokussieren können. Sobald sie platziert sind, werden wir schussbereit sein.\n\nIhr habt nur einen Versuch. Nutzt ihn!", sourceObjective = "Besiegt N'Zoth in Ny'alotha, der Erwachten Stadt.", completion = "Ihr habt es geschafft! N'Zoths Streitkräfte sind überall zerstreut, und seine Kontrolle über unsere Welt schwindet!\n\nIhr seid wahrlich ein Champion von Azeroth!", sourceObjectiveStatus = "unverified-source-field" }
quests[58634] = { id = 58634, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Öffnung des Tors", description = "Das Gewebe der Realität ist zerrissen. Aber das muss ich Euch ja nicht sagen, {name}. Ihr habt es mit eigenen Augen gesehen.\n\nEs ist nur eine Frage der Zeit, bevor unsere Realitäten verschmelzen und in ewige Finsternis gehüllt werden. Statt sich zu verstecken, ist es vielleicht an der Zeit, dass wir uns die Finsternis zu eigen machen.\n\nMit der Hilfe unseres Titanenfreunds hier könnten wir vielleicht den Faden dieser Realität durch das Gewebe einer anderen fädeln und so eine Art Brücke schaffen.\n\nDer Schlüssel zum Erkennen der Schwächen eines Gegners liegt schließlich darin, seine Absichten zu verstehen.", sourceObjective = "Sprecht mit MUTTER, um das schattenhafte Tor in der Herzkammer zu errichten.", progress = "Vor der Entdeckung steht die Ungewissheit.", completion = "Die Zeit ist für uns gekommen, der finstersten dieser Manifestationen entgegenzutreten.", sourceObjectiveStatus = "unverified-source-field" }
quests[58636] = { id = 58636, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blick auf die Amathet", description = "Im Namen der Forscherliga möchte ich mich bei Euch für Eure Hilfe dabei bedanken, das Abkommen von Uldum ins Leben zu rufen und uns eine gewisse Unterstützung von Ramkahen zu verschaffen.\n\nDamit wir unsere Feinde besser verstehen, hat Ramkahen uns gestattet, die Grabmäler der Amathet zu erkunden. Allerdings sind ihre Streitkräfte leider zu stark strapaziert, um uns Schutz zu gewähren.\n\nIch hatte gehofft, dass Ihr in diese Bresche springen könnt.\n\nKönnt Ihr vielleicht etwas Zeit erübrigen und nachsehen, was es damit auf sich hat? Wir können mit einem Blick aus der Luft beginnen.", sourceObjective = "Erkundet die Territorien der Amathet mit Hochforscherin Dellorah in Uldum.", progress = "Auf in den Himmel!", completion = "So viele neue Eindrücke! Ich wünschte nur, es wäre nicht so schwer, auf dem Rücken eines Greifen Notizen zu machen.\n\nDennoch glaube ich, dass wir hier nur die Spitze des Eisbergs entdeckt haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[58638] = { id = 58638, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefer eintauchen", description = "Irgendetwas passt bei diesen Amathet nicht recht zusammen. Wieso sollten Beschützer der Werke der Titanen die Schmiede des Ursprungs angreifen und beschädigen?\n\nIch denke, wir sollten uns das mal näher ansehen. Da drüben auf der Terrasse habe ich so etwas wie ein Monument gesehen, glaube ich. Vielleicht bieten uns die Inschriften darauf weitere Erkenntnisse über diese Tol'vir.", sourceObjective = "Verteidigt Hochforscherin Dellorah, während sie das Monument der Amathet auf der Sonnensteinterrasse entziffert.", progress = "Ich bin bereit, wenn Ihr es seid, {class}.", completion = "Dieses Monument war ein guter Anfang, aber es erklärt immer noch nicht, wonach wir suchen.\n\nGlücklicherweise ist die Forscherliga sehr gut darin, Geheimnisse zu lüften!", sourceObjectiveStatus = "unverified-source-field" }
quests[58639] = { id = 58639, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergrabene Geschichte", description = "Da die Amathet aus dieser Region stammen, ist es doch nur logisch, dass sie hier, versteckt unter dem Sand, Artefakte ihrer Zivilisation hinterlassen haben.\n\nEs ist wohl Zeit für eine gute altmodische Ausgrabung!\n\nDie Dünen in der Nähe müssten einen großen Teil des früheren Gebiets der Amathet bedecken. Sehen wir mal, was wir dort ausbuddeln können!", sourceObjective = "Entdeckt und sammelt 6 Artefakte der Amathet in Uldum.", progress = "Was habt Ihr entdeckt?", completion = "Jawohl! Die Zeichen auf diesen Artefakten bestätigen meine Hypothese.\n\nHier steckt auf jeden Fall mehr dahinter, als wir zunächst geglaubt haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[58640] = { id = 58640, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Sprung in der Rüstung", description = "Die Artefakte, bei deren Ausgrabung Ihr geholfen habt, stellen die Amathet als einen Stamm dar, dessen ganzer Stolz es war, die Werke der Titanen zu beschützen.\n\nDies bestätigt unsere Vermutungen und weist darauf hin, dass etwas Einschneidendes passiert sein muss, das sie veranlasst hat, die Werke zu beschädigen, die sie zu beschützen geschworen hatten.\n\nWir sollten weitere Schriften von ihnen aufspüren. Vor den Hallen des Ursprungs glaube ich, ein etwas jüngeres Monument gesehen zu haben.", sourceObjective = "Verteidigt Hochforscherin Dellorah, während sie das Monument der Amathet vor den Hallen des Ursprungs entziffert.", progress = "Ich kann kaum erwarten, dieses Geheimnis zu enträtseln!", completion = "Jemand oder etwas hat die Amathet von innen heraus manipuliert.\n\nDas klingt vertraut, meint Ihr nicht?", sourceObjectiveStatus = "unverified-source-field" }
quests[58641] = { id = 58641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbnissucher", description = "Falls jemand mehr über die auf der Tafel erwähnte \"Verderbnis\" weiß, dann die Sonnenberührten, die den Auftrag hatten, diese auszurotten.\n\nAllerdings bezweifle ich, dass sie irgendwelche Informationen freiwillig preisgeben würden.\n\nZum Glück für mich seid Ihr doch so eine Art Spezialist für gewaltsame Befragungen, nicht wahr?", sourceObjective = "Holt den Erlass des Sonnenkönigs von sonnenberührten Amathet in Uldum.", progress = "Habt Ihr etwas bei den Sonnenberührten gefunden?", completion = "Also arbeiten die Amathet doch nicht mit N'Zoth zusammen! Welch eine Erleichterung!\n\nNatürlich sind sie uns gegenüber dadurch nicht weniger feindlich eingestellt, aber das ist immerhin ein Anfang!", sourceObjectiveStatus = "unverified-source-field" }
quests[58642] = { id = 58642, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gemeinsame Ziele", description = "In dem Erlass, den Ihr gefunden habt, wird ein Plan erwähnt, um die Alten Götter zu besiegen.\n\nIch weiß, die Amathet werden wahrscheinlich nicht mit uns auf dieses Ziel hinarbeiten, aber wenn sie einen Plan haben, N'Zoth zur Strecke zu bringen, sollten wir uns den unbedingt ansehen.\n\nIn dem Erlass steht etwas von der Maschine des Aufstiegs. Ich glaube, so nennen sie das sonnenbetriebene Gerät, das wir kürzlich gesehen haben. Wir sollten einen Blick darunter werfen und versuchen, herauszufinden, was sie vorhaben!", sourceObjective = "Verteidigt Hochforscherin Dellorah, während sie Tafeln der Amathet in der Kammer der Sterne entziffert.", progress = "Dann sehen wir mal, was wir in der Kammer der Sterne finden können.", completion = "Diese Amathet haben sie doch nicht alle!\n\nSie haben entschieden, dass Azeroth unrettbar verloren ist!", sourceObjectiveStatus = "unverified-source-field" }
quests[58643] = { id = 58643, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegenseitig zugesicherte Vernichtung", description = "Die Amathet wollen die Schmiede des Ursprungs wieder übernehmen und sie dazu verwenden, jegliches Leben aus Azeroth zu tilgen... bis hin zu dem Alten Gott!\n\nSie könnten jederzeit zuschlagen. Wir müssen die Verteidiger der Schmiede warnen!", sourceObjective = "Warnt die Verteidiger der Hallen des Ursprungs vor dem Plan der Amathet.", completion = "Die Amathet... haben unsere Position gestürmt.\n\nWir waren... unterlegen...", sourceObjectiveStatus = "unverified-source-field" }
quests[58645] = { id = 58645, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettenswerte Welt", description = "Wir hatten ihnen nichts entgegenzusetzen. Ihre Krieger... eingehüllt in die Flammen der Sonne...\n\nSie wollen die Schmiede... um allem ein Ende zu bereiten...\n\nGeht... ich werde... schon durchhalten...", sourceObjective = "Verhindert, dass die Amathet die Hallen des Ursprungs übernehmen.", completion = "Ihr habt es geschafft! Ich kann nicht glauben, dass wir nur noch Momente vom Ende des Lebens, wie wir es kennen, entfernt waren!\n\nIch danke Euch für Eure Hilfe bei meiner Forschung, {class}. Ich möchte gar nicht wissen, wie das hier ohne Euch geendet hätte!\n\nWenn Ihr mich dann entschuldigen würdet, es wird Wochen dauern, alles zu katalogisieren, was wir gefunden haben!", sourceObjectiveStatus = "unverified-source-field" }
quests[58646] = { id = 58646, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Da habt Ihr was zum Beißen!", description = "Diese räudigen Hyänen zerkauen einfach alles, was sie ausgraben, und machen auch vor Artefakten von unschätzbarem Wert nicht Halt!\n\nWir dürfen nicht zulassen, dass die Geschichte von Uldum wortwörtlich vor die Hunde geht.\n\nIch fürchte, wir werden sie dezimieren müssen.", sourceObjective = "Tötet 8 Plünderer der Dünenläufer in Uldum.", completion = "Das war bedauerlich, aber notwendig.\n\nIch danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[58647] = { id = 58647, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerrissene Netze", description = "Mein Gatte diente einst unserem Volk als Elunes Sprecher - bis er zum Nachtkrieger wurde. Seine Gefühle dazu sind, gelinde gesagt... komplex.\n\nSpriggans haben die Seelennetze des Gartens zerfetzt. Würdet Ihr mir bitte helfen, sie zu reparieren? Ich werde unsere Geschichte schildern, während wir arbeiten.", sourceObjective = "Helft bei der Reparatur der Seelennetze.", completion = "Habt Dank, {name}. Mit etwas Hilfe ist es einfacher.\n\n\n\nHoffentlich habt Ihr keine schlechte Meinung von Thiernax. Unangebrachte Schuldgefühle und Reue prägen seine Beziehung zum Nachtkriegerritual, aber ich kann ihn sicherlich umstimmen. Er wird seine Hilfe anbieten.", sourceObjectiveStatus = "unverified-source-field" }
quests[58654] = { id = 58654, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bitte an die Ernter", description = "Ihr kommt zu wahrlich seltsamen Zeiten. Die geforderten Abgaben an den Zehntherrn steigen von Tag zu Tag, und unsere Möglichkeiten, an Anima zu kommen, schwinden immer mehr.\n\nDie Seelen, mit denen wir hier arbeiten müssen, stehen kurz vor ihrem letzten Urteil, und wir haben einfach nicht die Ressourcen, sie zu ernten, ohne den Weiler zu gefährden.\n\nWenn der Oberste Kämmerer Euch Gehör schenkt, könnt Ihr dem Meister selbst vielleicht eine Nachricht überbringen.\n\nHier, nehmt diesen Brief. Stellt sicher, dass der Oberste Kämmerer ihn erhält.", sourceObjective = "Überbringt Mihaelas Notiz dem Obersten Kämmerer.\n\nBereitgestellter Gegenstand:", completion = "Oh, die Arbeiter bitten also tatsächlich um Hilfe?\n\nWer loyal ist, weiß, dass Opfer einen essenziellen Bestandteil des Überlebens in Revendreth darstellen. Ja, es sind dunkle Zeiten, da es an Anima und neuen Seelen mangelt.\n\nWir müssen aber alle unseren Beitrag leisten, egal wie schmerzlich das auch sein mag.", sourceObjectiveStatus = "unverified-source-field" }
quests[58656] = { id = 58656, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwer wiegt das Haupt...", description = "Krone ist instabil, weil der Graf durch Medaillons immer noch Einfluss hat. Ein Testlauf sollte das lösen.\n\nHabe eines Eurer Medaillons gesockelt. Seht, wie seine Macht in einer Waffe der Zerstörung konzentriert wird. \n\nPerfekte Gelegenheit. Verschmähte haben Konstruktion von Kolossen abgeschlossen. Zerstört sie. Bringt den Verschmähten das Ende, das sie herbeisehnen.\n\nVorsicht. Theotar hat mir gesagt, wie mächtig diese Magie ist. Die Krone ist unersättlich, muss kontrolliert werden.", sourceObjective = "Testet die Krone der Ernter und besiegt die einsatzfähigen Kolosse.", completion = "Ihr lebt. Die Krone hat angefangen, sich von Eurer Seele zu nähren.\n\nSieht so aus, als gäbe es immer noch Arbeit zu tun. Mikanikos sagt, dass Einfluss des Grafen immer noch in der Krone ist.\n\nEr sagt, er hat einen Plan.", sourceObjectiveStatus = "unverified-source-field" }
quests[58660] = { id = 58660, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grabende Schrecken" }
quests[58661] = { id = 58661, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grabende Schrecken" }
quests[58662] = { id = 58662, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grabende Schrecken" }
quests[58664] = { id = 58664, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ultimative Generalüberholung", description = "Wir beherrschen jetzt den Apparat der Monstrositätenkonstruktion! Jetzt können wir neue Konstrukte für würdige Seelen schaffen.\n\nEmeni sollte die Erste sein. Ihre Kampffertigkeiten sind unübertroffen, und Ihr werdet sie brauchen, um den Flickenhof zu sichern.\n\nIhr helft mir dabei, Emenis Konstrukt neu zu bauen.", sourceObjective = "Helft Rathan, Emenis Konstrukt neu zu bauen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58665] = { id = 58665, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rebellische Seelen", description = "Bitte hört uns an.\n\nAls Markgraf Gharmal die Bastion angegriffen hat, haben sich viele wie Emeni und ich gegen ihn gestellt.\n\nGharmal befürchtete Widerstand, entfernte viele Seelen aus ihren Konstruktkörpern und hielt sie gefangen. Emeni entkam, aber die meisten nicht.\n\nHelft uns, die anderen Seelen zu befreien und wir können Euch eine Armee der Konstrukte bauen, die alles übertrifft, was in Gharmals Diensten steht.", sourceObjective = "Trefft Rathan und Emeni am Sechsbeinpass.", completion = "Lasst Euch von Emenis grummeliger Natur nicht abschrecken. Wir sind Euch für Eure Hilfe sehr dankbar!", sourceObjectiveStatus = "unverified-source-field" }
quests[58667] = { id = 58667, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Obsidianextraktion" }
quests[58668] = { id = 58668, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Findet den Weg", description = "Viele Äonen lang war ich Lehrling am Flickenhof. Ich habe sogar im Leichendepot mit Chirurg Fleischnaht gearbeitet, um Emenis letztes Konstrukt zu entwerfen.\n\nWenn wir das Leichendepot unter unsere Kontrolle bringen, haben wir die nötigen Teile, um Emeni neu zu bauen und neue Körper für die geretteten Seelen zu schaffen. \n\nFührt uns dorthin, und wir versuchen, es zum Laufen zu bringen.", sourceObjective = "Führt Rathan und Emeni zum Leichendepot.", completion = "Ich hätte nie gedacht, dass ich an diesen Ort zurückkehre.", sourceObjectiveStatus = "unverified-source-field" }
quests[58669] = { id = 58669, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leicht zurechtstutzen", description = "Spriggans dringen manchmal in den Garten ein, um Unheil und Chaos zu verbreiten. Der Ärger, den sie mit sich bringen, nimmt kein Ende...\n\nEigentlich hält die Wilde Jagd sie in Schach... aber ihre Jäger und Jägerinnen haben in letzter Zeit weitaus dringendere Sorgen. Thiernax und ich haben geholfen, den Garten freizuhalten, aber er ist fortgelaufen, um irgendwo zu grübeln.\n\n<Qadarin schüttelt den Kopf.>\n\nIhr würdet mir einen großen Gefallen tun, wenn Ihr mir helft, den Garten der Königin von diesem Ungeziefer zu befreien.", sourceObjective = "Tötet 15 Sicheldornspriggans.", completion = "Das haben sie hoffentlich verstanden und verschwinden wieder!", sourceObjectiveStatus = "unverified-source-field" }
quests[58670] = { id = 58670, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Mördertochter", description = "Als ich eingesperrt war, habe ich eine Liste mit allen Konstrukten aufgesetzt, die mich verraten haben... es ist eine lange Liste!\n\nHelft mir, diesen Konstrukten die Fehler aufzuzeigen, die sie gemacht haben. Ich möchte jeden auf meiner Liste zerstören, auch Hofmeister Pralak, der an erster Stelle steht!", sourceObjective = "Helft Emeni, jeden auf ihrer Liste zu töten.", completion = "Ich denke, das war deutlich, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[58671] = { id = 58671, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angestaut", description = "Es gab viele Seelen, die sich gegen Markgraf Gharmals Angriff auf die Bastion gewehrt haben. Wer die Stimme erhoben hat, dem wurde der Körper genommen und wir wurden im Ätherischen Gewölbe eingesperrt, bis unsere nach Anima hungernden Seelen verblasst waren.\n\nMeine Freunde sind noch immer in den Gewölben eingekerkert. Wir werden sie befreien und eine Armee der Konstrukte bauen, die für Euch kämpft!", sourceObjective = "Rettet 10 gefangene Seelen im Ätherischen Gewölbe.", completion = "Wir bilden ein gutes Team, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[58672] = { id = 58672, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Zusammenkunft der Champions", description = "Die Anführer der Horde sammeln sich in Orgrimmar, um den neuen Kriegshäuptling der Horde zu wählen.\n\nAls Champion der Horde ist Eure Anwesenheit bei der Versammlung erwünscht. Die Zusammenkunft findet in der Botschaft von Orgrimmar statt.\n\nIch gehe schon voraus. Sprecht mit mir, wenn Ihr in Orgrimmar ankommt. Ich werde mit den anderen auf Euch warten.\n\nBeeilt Euch, Champion. Die Zukunft der Horde wird sich dort entscheiden...", sourceObjective = "Sprecht mit Valeera Sanguinar in Orgrimmar.", completion = "Ihr seid genau rechtzeitig gekommen. Die Versammlung beginnt gleich.", sourceObjectiveStatus = "unverified-source-field" }
quests[58673] = { id = 58673, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegshäuptling der Horde", description = "Die Versammlung zur Bestimmung des nächsten Kriegshäuptlings der Horde beginnt in Kürze.\n\nDie anderen Anführer der Horde sind bereits hier. Sie warten in der Botschaft auf Euch.\n\nSprecht mit mir, wenn Ihr bereit seid, dann begrüßen wir die anderen gemeinsam.", sourceObjective = "Erlebt die Zusammenkunft der Champions mit.", completion = "Die Entscheidung steht also. Es wird keinen Kriegshäuptling der Horde mehr geben.\n\nWir waren hier offenbar Zeugen des Anfangs eines neuen Zeitalters...", sourceObjectiveStatus = "unverified-source-field" }
quests[58674] = { id = 58674, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Zusammenkunft der Champions", description = "König Wrynn hat eine Unterredung mit den Allianzanführern in Sturmwind einberufen.\n\nUm Eure Anwesenheit bei der Zusammenkunft wurde ausdrücklich gebeten. Die Versammlung wird in der Botschaft abgehalten.\n\nKommt zu mir, wenn Ihr in Sturmwind eintrefft, ich werde bei den anderen warten.\n\nIhr solltet Euch beeilen, {name}. Es wäre höchst unklug, den König warten zu lassen...", sourceObjective = "Sprecht mit Meister Mathias Shaw in Sturmwind.", completion = "Ihr seid genau rechtzeitig gekommen. Der König wird in Kürze mit seiner Ansprache beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58675] = { id = 58675, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Preis des Friedens", description = "Der König wird uns in Kürze Neuigkeiten von seiner diplomatischen Mission zur Horde verkünden.\n\nDie anderen Anführer der Allianz sind bereits eingetroffen. Ich bin sicher, sie können kaum erwarten, zu hören, was König Wrynn zu erzählen hat.\n\nSprecht mit mir, wenn Ihr bereit seid, dann begrüßen wir den König gemeinsam.", sourceObjective = "Wohnt König Wrynns Ansprache bei.", completion = "Hmm... Sieht so aus, als ob das Treffen nicht ganz so verlaufen ist, wie der König es erwartet hatte. Wir kennen den Standpunkt von Genn und Tyrande, aber ich frage mich, was die anderen zu sagen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[58676] = { id = 58676, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlummernder Zerstörer" }
quests[58677] = { id = 58677, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es geht um die Haut", description = "Diese Aufgabe übersteigt vermutlich Eure Fähigkeiten, aber hört trotzdem zu.\n\nAls Konstrukt war ich in den ganzen Schattenlanden gefürchtet. Der hervorragenden Haut meines Konstrukts konnten sterbliche Waffen nichts anhaben. Sie war ein Kunstwerk, das über Jahre perfektioniert wurde.\n\nAls ich aus meinem Konstrukt entfernt wurde, bereitete es Faldo Iscar große Freude, diese Haut zu stehlen. Er trägt sie als Souvenir bei sich.\n\nTötet Faldo Iscar und holt meine Haut zurück!", sourceObjective = "Emenis hervorragende Haut erhalten", progress = "Als ich noch am Leben war, hätten wir Freunde sein können... Oder Ihr wärt mein Abendessen gewesen.", completion = "Mein kaltes Blut erwärmt sich für Euch. Ihr könntet ein passender Verbündeter sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[58679] = { id = 58679, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlummernder Zerstörer" }
quests[58680] = { id = 58680, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lose Fäden", description = "Uns fehlen einige Werkzeuge und Teile, um ein Konstrukt zu nähen. Wir brauchen diese Gegenstände, wenn wir mein Konstrukt neu bauen wollen!\n\nSucht die Umgebung ab. Vielleicht könnt Ihr finden, was wir brauchen.\n\nSucht auf den Tischen nach Spießnadeln, fragt Knechte nach Klingenzwirnspulen und haltet Ausschau nach Gerinnungsflicken bei den Konstrukten, die Ihr tötet.", sourceObjective = "Findet Spießnadeln, Klingenzwirnspulen und Gerinnungsflicken.", progress = "Ihr seid gut darin.", completion = "Ihr solltet über ein Körperkonstrukt nachdenken. Vielleicht kann ich eines Tages eines für Euch entwerfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58686] = { id = 58686, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Massenkonstruktionswaffe", description = "Wir haben Glück!\n\nChirurg Fleischnaht und sein Assistent sind noch nicht aus der Bastion zurück. Der komplette Flickenhof ist nur leicht bewacht.\n\nWir müssen schnell arbeiten. Seht zu, ob Ihr die Ausrüstung zum Laufen bringt. Dann können wir mit der Konstruktion beginnen.", sourceObjective = "Macht das Konstruktionslabor einsatzbereit.", completion = "Wir sind fast fertig! Nur noch ein Schritt, um die Konstruktion abzuschließen!", sourceObjectiveStatus = "unverified-source-field" }
quests[58704] = { id = 58704, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Garten der Nacht", description = "Das sollte die Dinge hier draußen in Ordnung bringen. Jetzt müssen wir uns um den inneren Garten kümmern. Sobald wir fertig sind, kümmere ich mich um meinen eigensinnigen Gatten.\n\nHoffentlich haben sich die restlichen Spriggans von selbst verzogen, nachdem wir die anderen abgefertigt haben.", sourceObjective = "Tötet Spriggans in den inneren Gärten.", completion = "Ich hätte nie weggehen dürfen! Er hat mir immer wieder gesagt, ich solle mich meiner...\n\nEgal. Darum kann ich mich später kümmern.\n\nDie Situation wäre viel schlimmer gewesen, wenn Ihr beide nicht hier gewesen wärt.", sourceObjectiveStatus = "unverified-source-field" }
quests[58705] = { id = 58705, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großkaiserin Shek'zara" }
quests[58706] = { id = 58706, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausweiden der Beute", description = "<Huln hört Eure Erklärung an und hält dann inne.>\n\nIch verstehe, {name}. Aber ich kann Euch nicht sofort helfen.\n\nLasst es mich Euch erklären. Helft Ihr mir in der Zwischenzeit, diesen Kadaver zu zerlegen? Man kann immer von seiner Beute lernen.", sourceObjective = "Helft Huln Hochberg dabei, den Verschlinger zu zerlegen.", progress = "Je schneller Ihr ihn zerlegt, desto schneller kann ich Euch helfen.", completion = "Hervorragend. Das bestätigt meinen Verdacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[58707] = { id = 58707, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Visionenordnung" }
quests[58708] = { id = 58708, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine phägnomenale Entdeckung", description = "Tüftlermeister Oberfunks hat Eure Unterstützung bei einer wichtigen Forschungsexpedition angefordert.\n\nMit dem angesehenen Tüftlermeister zu arbeiten wird Eure Karriere sicherlich vorantreiben. Meine hat davon außerordentlich profitiert.", sourceObjective = "Trefft Euch mit Tüftlermeister Oberfunks in Boralus.", completion = "Jetzt kann unsere Expedition beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58714] = { id = 58714, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Wald hat Augen", description = "Dieser Traum! Der mit den Zähnen und den Klauen und dem herz... herzzerreißenden Opfer?\n\n<Mondbeere schnürt es einen Moment die Kehle zu, dann sammelt sie sich.>\n\nVerzeiht! Während wir im Traumland waren, sind besessene Spione ins Winterschlafbecken eingedrungen!\n\nJagt und vernichtet sie, bevor sie über die Verteidigung des Hains Bericht erstatten können.\n\nHier, nehmt etwas von meiner Magie. Sucht die in den Schatten Versteckten und streckt sie nieder!", sourceObjective = "Tötet versteckte besessene Spione im Winterschlafbecken.", completion = "Diese Drust sind sehr dreist und schicken Spione in meinen Hain! Sehr dreist... und sehr töricht.", sourceObjectiveStatus = "unverified-source-field" }
quests[58717] = { id = 58717, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glocke der Erinnerung", description = "<Die Glocke ist verkratzt und ramponiert. Ihr erinnert Euch, dass die Kuratorin sehr an diesem Gegenstand interessiert war.\n\nVielleicht weiß jemand in der Gruft der Vergessenen mehr darüber.>", sourceObjective = "Sucht jemanden in der Gruft der Vergessenen, der mehr über die Glocke weiß.", completion = "Seid gegrüßt, Schlundgänger.\n\nWarum seid Ihr zu mir gekommen? Ich habe schon viel von Euch gehört.", sourceObjectiveStatus = "unverified-source-field" }
quests[58719] = { id = 58719, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf der Dromanen", description = "Unsere Feinde kommen schnell näher, {name}. Wir müssen den Ruf ertönen lassen, um den Hain zu verteidigen!\n\nBenutzt dieses Horn, um unsere Beschützer zu rufen. Ruft die Wilde Jagd herbei, um jene zu töten, die uns angreifen wollen.", sourceObjective = "Lasst das Dromanenhorn ertönen, um die Wilde Jagd zu den Eingängen des Hains zu rufen.", progress = "Die Jagd wird unseren Ruf hören und losreiten, um den Hain zu verteidigen!", completion = "Die Wilde Jagd reitet uns zu Hilfe... nur nicht aus dem Westen?\n\nDort war Jagdhauptmann Korayn einem gefährlichen Feind auf den Fersen. Man muss ihr und ihrem Jagdtrupp aufgelauert haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[58720] = { id = 58720, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vermisst!", description = "Die Wilde Jagd ist dem Ruf gefolgt, uns zu verteidigen... bis auf Jagdhauptmann Korayn und ihre Truppen.\n\nSie hatte ihren Jagdtrupp nach Westen geführt, einem mächtigen Feind auf der Spur. Möglicherweise haben sie Schwierigkeiten.\n\nFindet sie und leistet ihr jegliche Unterstützung, die sie benötigt.\n\nWir brauchen ihre Jäger und ihre Führungsqualitäten, wenn unsere Verteidigung standhalten soll.", sourceObjective = "Findet Jagdhauptmann Korayn auf dem Pfad der Wiedergeburt.", completion = "Diese Drust hatten vor, Truppen zu entsenden, die uns von hinten angreifen sollten.\n\n<Korayn grinst.>\n\nEuer Ruf hat die anderen Jäger und Jägerinnen herbeigeholt, um uns Verstärkung zu leisten, und dann waren es die Drust, die überrumpelt wurden.", sourceObjectiveStatus = "unverified-source-field" }
quests[58721] = { id = 58721, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weckt die Träumerin", description = "Die Königin konzentriert sich größtenteils auf den Hain des Erwachens, wo wiederhergestellte Geister aus ihren Wildsamen hervorkommen, um in ihre Welt zurückzukehren.\n\nVielleicht ist es gut, dass Ihr einen verwundeten Geist bei Euch habt.\n\n<Lord Herne betrachtet Yseras Wildsamen einen Moment lang. Dann breitet sich langsam ein Grinsen auf seinem Gesicht aus.>\n\nDie hier kämpft mit ihrem gesamten Wesen. Sogar jetzt klammert sie sich noch an ihre Existenz.\n\nKommt, <Fremder/Fremde>, lasst uns herausfinden, welches Schicksal die Königin für sie vorgesehen hat.", sourceObjective = "Reist zum Hain des Erwachens.", completion = "<Die Winterkönigin richtet ihren Blick auf Euch.>\n\nWie sonderbar, jemanden wie Euch in meinem Wald zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58723] = { id = 58723, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hof des Winters", description = "Mein Hofstaat berichtet mir, dass Ihr eine wichtige Botschaft habt.\n\nTragt sie bitte vor.", sourceObjective = "Übergebt die Botschaft des Primus der Winterkönigin.", progress = "Der Erzfeind war nicht untätig...", completion = "Der Verbannte regt sich und die Macht des Ardenwalds welkt in der Dürre dahin.", sourceObjectiveStatus = "unverified-source-field" }
quests[58724] = { id = 58724, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bitte der Königin", description = "Finstere Vorzeichen.\n\nIch habe die wenige Anima, die wir besitzen, zur Rettung unserer Haine und der von ihnen genährten Geister verwendet. Wir haben so viele verloren... und das Herz des Waldes wurde dabei immer schwächer.\n\nDen Verbannten im Schlund festzuhalten wird mehr Anima erfordern, als der Ardenwald entbehren kann.\n\n<Die Königin denkt einen Moment nach.>\n\nGraf Denathrius ist ein Meister der Animaextraktion. Geht nach Revendreth und berichtet ihm von unserer Zwangslage. Ich weiß, er wird uns unterstützen.\n\nEure Verbündeten in Oribos können den Weg freimachen.", sourceObjective = "Kehrt zu Tal-Inara in Oribos zurück.", completion = "Was ist im Ardenwald geschehen? Erzählt mir alles.", sourceObjectiveStatus = "unverified-source-field" }
quests[58725] = { id = 58725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sündenhüter", description = "Das ist eine Glocke der Erinnerung. Vor den letzten... \"Ereignissen\" haben wir sie benutzt, um Seelen aus der Gruft der Vergessenen zu locken, um über ihr Schicksal zu entscheiden.\n\nSind sie weniger hochmütig als zuvor, dürfen sie den Prozess fortführen. Wenn nicht, bleiben sie in der Gruft.\n\nSollen wir die Glocke einsetzen? Sie ist ziemlich ramponiert, hoffentlich funktioniert sie noch einmal.", sourceObjective = "Benutzt die Glocke der Erinnerung, um eine Seele aus der Gruft der Vergessenen zu locken. Entscheidet dann über ihr Schicksal.", completion = "Habt Dank, {name}. Ihr habt dieser Seele geholfen, auch wenn es sich nicht so anfühlt.", sourceObjectiveStatus = "unverified-source-field" }
quests[58726] = { id = 58726, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dicke Haut", description = "Der Primus hat eine gute Klinge geschmiedet, aber in diesem Zustand wird sie Euch nicht viel nützen.\n\nZu Eurem Glück besitze ich die Fertigkeit, seine Arbeit fertigzustellen!\n\nDazu brauche ich allerdings Materialien. Die anderen Auserwählten waren zu beschäftigt mit ihren Kampfübungen, um mir in der Schmiede zu helfen. Auch dann, als sie nach mehr Waffen und Rüstung schrien.\n\nHier kommt Ihr ins Spiel. Ihr wollt eine neue Klinge? Die müsst Ihr Euch verdienen.", sourceObjective = "Sammelt 40 pulsierende Hautfetzen von wuchernder Masse.", progress = "Kann doch nicht so schwierig sein, oder?", completion = "Ihr arbeitet schnell, was? Ich könnte mehr Assistenten wie Euch brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58727] = { id = 58727, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Zuhause", description = "Ihr seid nicht auf meiner Liste gelandet... Dann sind wir wohl Freunde... für den Augenblick.\n\nRathan hat die befreite Seele zum Metzgerblock nahe des Sitzes des Primus gebracht. \n\nTreffen wir ihn dort und planen gemeinsam unseren nächsten Schritt.", sourceObjective = "Trefft Euch mit Rathan und Emeni am Metzgerblock.", completion = "Dieser Ort ist wie gemacht für uns. Wir können neue Konstrukte und ein Zuhause für uns bauen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58737] = { id = 58737, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magnis Erkenntnisse", description = "Nicht nur, dass wir die Schmiede wieder in Betrieb nehmen konnten, wir haben vielleicht auch noch den Schlüssel gefunden, um N'Zoth ein für alle Mal in den Archiven des Mogu'shangewölbes zu vernichten.\n\nVielleicht wollt Ihr Euch lieber setzen, Champion.", sourceObjective = "Erfahrt von Magnis Erkenntnissen.", completion = "Sieht so aus, als ob wir einen Plan haben!\n\nJetzt lasst uns mal sehen, was Furorion ausgebrütet hat, um Ny'alotha zu finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[58740] = { id = 58740, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterjochte Schlangen", description = "Überall, wo die Zan-Tien auftauchen, folgen ganz sicher auch Kriegsschlangen.\n\nIch kann nicht genug betonen, wie gefährlich diese Bestien sind. Es ist eine Schande, dass sie von den Mogu unterjocht wurden, aber wir können nicht zulassen, dass sie Amok laufen.\n\nIhr müsst sie ausschalten, bevor sie in unseren Reihen Chaos anrichten.", sourceObjective = "Tötet 4 Onyxkriegsschlangen im Tal der Ewigen Blüten.", completion = "Es ist nicht schön, mitansehen zu müsssen, wie die Wolkenschlangen dezimiert werden, aber die Zan-Tien haben sie so weit verdorben, dass es kein Zurück mehr gibt.\n\nKeine Sorge, sie werden dafür bezahlen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58741] = { id = 58741, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steinschneider", description = "Ein Problem bei der Kriegsführung gegen andere Mogu ist, dass unsere Waffen gegen Feinde aus Metall und Stein schnell stumpf werden und brechen.\n\nAls einziger Schmied unter den Rajani, ist es oftmals nicht möglich, den Bedürfnissen einer ganzen Kriegerarmee gerecht zu werden.\n\nWenn Ihr bei Euren Kämpfen gegen die Mogu irgendwelche Waffen findet, kann ich diese sicherlich gut gebrauchen.", sourceObjective = "Sammelt 10 Moguwaffen im Tal der Ewigen Blüten.", progress = "Was habt Ihr entdeckt?", completion = "Diese Waffen sehen aus, als wären sie noch gut in Schuss.\n\nSie werden unseren Kriegern gut dienen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58742] = { id = 58742, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Retinus der Sucher", sourceObjective = "Besiegt Grixis Winzplopp in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[58743] = { id = 58743, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dünenkrabbler", sourceObjective = "Besiegt Grixis Winzplopp in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[58744] = { id = 58744, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich bin der, der flüstert", sourceObjective = "Besiegt Grixis Winzplopp in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
