quests[58748] = { id = 58748, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lebende Statuen sind hart", sourceObjective = "Besiegt Grixis Winzplopp in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[58749] = { id = 58749, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flug der Vil'thik", sourceObjective = "Besiegt Grixis Winzplopp in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[58750] = { id = 58750, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Packt den Stier bei den Hörnern", description = "Ich habe mir hier einen ziemlichen Namen als Tauralusbändiger gemacht. Jeder will einen Tauralus!\n\nIhr erledigt etwas Arbeit für mich, und die Leute werden bald auch wissen, wer Ihr seid.\n\nNehmt diesen Knochensplitter und spießt Euch ein paar saftige Knabberer auf. Lockt damit einen Tauralus an und reitet ihn zurück zu mir.", sourceObjective = "Reitet 5 Blutnarbentauralusse zurück zu Dundae.", progress = "Wollt Ihr berühmt werden? Habt Ihr die Tauralusse, die ich wollte?", completion = "Das sind ein paar gute Tauralusse. Danke für die Hilfe, Sterblicher!", sourceObjectiveStatus = "unverified-source-field" }
quests[58751] = { id = 58751, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine geteilte Gefahr", description = "Jedes Haus in Maldraxxus hat zwei Barone. Bevor mein erstes Haus, das Haus der Augen, gefallen ist, hat unser Markgraf eine Baronin entsandt, verdächtiges Verhalten im Haus der Rituale zu untersuchen.\n\nSeither habe ich nicht von ihr gehört. Entweder hat sie etwas entdeckt... oder fiel dem Verrat zum Opfer. \n\nIhre Befehle führten sie zum Verfall in den Osten. Wenn Ihr die Baronin findet, gebt Ihr diese Vorladung. \n\nSie und ich waren keine Freunde, aber sie ist eine hervorragende Kämpferin. Wir könnten ihre Stärke brauchen.", sourceObjective = "Findet die Baronin in der Bastille der Abschwur.", progress = "Jemand Neues... Und doch jemand Vertrautes.", completion = "Seid dankbar, dass ich Euch hier gefunden habe.\n\nAndere in Maldraxxus hätten vielleicht kein Potenzial in Eurer Stärke erkannt.", sourceObjectiveStatus = "unverified-source-field" }
quests[58754] = { id = 58754, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champions des Schwarms", description = "Es ist offensichtlich, dass Shek'zara alles in diese Invasion investiert. Unsere Späher haben einige ihrer besten Champions auf dem Schlachtfeld ausgemacht.\n\nJeder dieser Mantis könnte für die Soldaten des Goldenen Lotus zu stark sein. Wir müssen sie selbst jagen und ausschalten.\n\nSeid Ihr dabei?", sourceObjective = "Besiegt 3 seltene Mantisgegner im Tal der Ewigen Blüten.", completion = "Beeindruckende Trophäenanzahl. Ihr habt fast so viele gesammelt wie ich.\n\nVielleicht beim nächsten Mal.", sourceObjectiveStatus = "unverified-source-field" }
quests[58755] = { id = 58755, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versteckte Vorräte", description = "Die einfallenden Mantis haben sich vor Kurzem mit den Vorräten des Goldenen Lotus aus dem Staub gemacht. Sie wollen uns wohl aushungern.\n\nDas schaffen sie vielleicht auch, wenn wir nicht wenigstens einen Teil unserer Vorräte zurückholen können.\n\nAchtet beim Kampf gegen den Schwarm darauf, wo sie die Vorräte aufbewahren könnten. Ihr würdet dem Goldenen Lotus einen großen Dienst erweisen, wenn Ihr welche zurückbringt.", sourceObjective = "Sammelt 3 Vorräte des Goldenen Lotus aus bernbesetzten Truhen im Tal der Ewigen Blüten.", progress = "Habt Ihr unsere Vorräte aufgespürt?", completion = "Ihr habt sie gefunden! Was für ein Glück!\n\nDiese Vorräte werden uns beim Kampf gegen die Mantis helfen, vielleicht sogar so lange, bis wir sie wieder zurückschlagen können!\n\nDer Goldene Lotus steht in Eurer Schuld!", sourceObjectiveStatus = "unverified-source-field" }
quests[58756] = { id = 58756, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grausige Heiler", description = "Die Bernzauberer gehören zu den höchsten Kasten der Mantisgesellschaft. Mit ihrer Magie können sie Bern nach ihrem Willen verformen und so die erneute Kampfbereitschaft der Mantis nach Schlachten enorm beschleunigen.\n\nSie sind strategische Ziele, die wir ausschalten sollten.\n\nWollt Ihr uns helfen?", sourceObjective = "Tötet 6 Bernzauberer der Mantis im Tal der Ewigen Blüten.", completion = "Ohne Einheiten, die ihre verwundeten Soldaten heilen, ist es nur noch eine Frage der Zeit, bis wir sie in die Ödnis zurückgetrieben haben.\n\nGute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[58757] = { id = 58757, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Testen der Prüflinge", description = "Wenn sie schwärmen, schicken die Mantis ihre Jüngsten in Massen gegen ihre Gegner, um ihre Eignung zu testen. Die Überlebenden werden als wahre Krieger der Mantis Teil des Schwarms.\n\nWir sollten mit allen Mitteln dafür sorgen, dass keiner von ihnen diesen Test überlebt.", sourceObjective = "Tötet 12 Schwarmgeborene der Vil'thik im Tal der Ewigen Blüten.", completion = "Die Mantis schicken solch unerfahrene Kreaturen gegen kampferprobte Einheiten. Was für ein Wahnsinn.\n\nHoffentlich lernen sie diese Lektion niemals.", sourceObjectiveStatus = "unverified-source-field" }
quests[58758] = { id = 58758, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wilde Zerstörer", description = "Der letzte Angriff der Mantis ist in der Erinnerung des Goldenen Lotus noch sehr präsent. Direkt vor dem eigentlichen Einfall des Schwarms schickten sie ihre riesigen Kunchong voraus, um die Verteidigungslinien zu schwächen.\n\nIhre Taktik hat sich anscheinend nicht geändert.\n\nWir müssen diese Kunchong aufhalten, wenn der Goldene Lotus die Verteidigung gegen den Schwarm aufrechterhalten soll. Ich zähle dabei auf Euch.", sourceObjective = "Tötet 4 Kunchongzerstörer im Tal der Ewigen Blüten.", completion = "Die Kunchong sind gefährliche Bestien. Ihr seid wahrlich tapfer, Euch ihnen zu stellen.\n\nDer Goldene Lotus dankt Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[58759] = { id = 58759, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Garde der Kaiserin", description = "Die Zara'thik sind die Elitegarde der Kaiserin. Durch das geplünderte Azerit sind sie so mächtig, dass nichts sie von der absoluten Eroberung ganz Pandarias abhalten kann.\n\nWenn sie noch weiter als zum Schlangenrücken vorpreschen, wird der Goldene Lotus kein Gegner mehr für sie sein.\n\nHaltet sie an der Mauer auf, {class}.", sourceObjective = "Tötet 8 Mantis der Zara'thik im Tal der Ewigen Blüten.", completion = "Ihr habt ihren Vormarsch aufgehalten. Das muss vorerst genügen.\n\nIch werde Euch alarmieren, wenn sich die Situation verschlimmert.", sourceObjectiveStatus = "unverified-source-field" }
quests[58760] = { id = 58760, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klingen aus Bern", description = "Die Mantis sind zerbrechlich und schwach, aber ihre Bernwaffen sind beeindruckend.\n\nMit ein wenig Arbeit könnten sie so umgeformt werden, dass sie sich für die Mogu eignen.\n\nBringt mir solche Waffen und ich mache sie für die Rajani nutzbar.", sourceObjective = "Sammelt 12 Bernklingen von Vil'thikmantis im Tal der Ewigen Blüten.", progress = "Habt Ihr mir Klingen mitgebracht?", completion = "Es wundert mich, wie eine solche stabile und scharfe Klinge aus einem solch zerbrechlichen Objekt wie einem Baum geschaffen werden kann.\n\nVielleicht können wir von den Mantis doch noch etwas lernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58761] = { id = 58761, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Füßen getreten", description = "In der Vergangenheit haben die Mantis ihre Jungtiere in Inkubationskammern gehütet, bis sie bereit waren, für den Schwarm geprüft zu werden.\n\nDie Vil'thik sind allerdings nicht so sorgsam. Ihre Larven wuseln völlig schutzlos überall herum.\n\nWäre es nicht zu schade, wenn sie jemand einfach zermatschen würde?\n\nNein, natürlich nicht.", sourceObjective = "Zermatscht 10 Larven der Vil'thik im Tal der Ewigen Blüten.", completion = "Die Zukunft unserer Feinde einfach mit den Füßen zu zertreten...\n\nEin tolles Gefühl, nicht wahr?", sourceObjectiveStatus = "unverified-source-field" }
quests[58762] = { id = 58762, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefangene des Schwarms", description = "Dieser Mantisschwarm ist anders. Sie töten nicht einfach alles, was sie sehen, wie Mantis es gewöhnlich tun. Stattdessen halten sie unsere Verteidiger lebendig gefangen.\n\nIch will nicht wissen, was sie mit den Gefangenen vorhaben.\n\nRettet sie bitte, damit wir gar nicht erst herausfinden müssen, welcher Plan dahintersteckt.", sourceObjective = "Befreit 6 Gefangene des Goldenen Lotus aus gehärteten Bernkäfigen im Tal der Ewigen Blüten.", completion = "Ihr habt sie befreit? Was für eine Erleichterung!\n\nIch kann mir nicht vorstellen, was ein Mantis mit lebenden Gefangenen vorhat. Mit Sicherheit nichts Gutes!", sourceObjectiveStatus = "unverified-source-field" }
quests[58763] = { id = 58763, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Produktionsstopp", description = "Bern wird von den Mantis für alles Mögliche verwendet, von ihren Gebäuden bis hin zu ihren Waffen. Die Waffen interessieren mich natürlich mehr.\n\nWenn wir den Mantis ihre Materialien wegnehmen, haben sie keine Rohstoffe mehr, um Kriegswaffen herzustellen.\n\nFindet ihre Bernlager und macht die Rohstoffe unbrauchbar.", sourceObjective = "Zerstört 6 Berngefäße im Tal der Ewigen Blüten.", completion = "Ohne ihren wertvollen Bern haben die Mantis keinen Nachschub mehr.\n\nGut gemacht, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[58764] = { id = 58764, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Standarten des Schwarms", description = "Diese dreisten Mantis fühlen sich schon als Sieger. Sie pflanzen ihre Banner entlang des Schlangenrückens auf und stellen ihre Dominanz zur Schau.\n\nSie müssen lernen, dass Pandaria den Pandaren gehört.\n\nVerbrennt ihre Banner.", sourceObjective = "Verbrennt 6 Banner der Zara'thik im Tal der Ewigen Blüten.", completion = "Ihre Zeichen wurden aus dem Tal getilgt. Ihren Truppen wird bald das gleiche Schicksal widerfahren.\n\nIch hoffe, ich kämpfe an Eurer Seite, wenn wir sie endlich hinter den Schlangenrücken zurücktreiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[58765] = { id = 58765, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Belagerungsbrecher", description = "Der Goldene Lotus kann zweifelsohne den Mantiskriegern standhalten. Ihre Kriegswagen allerdings können eine komplette Einheit unserer Verteidiger mit einem einzigen Angriff zerschmettern.\n\nWenn wir in dieser Schlacht die Oberhand behalten wollen, muss jemand ihre Stellungen infiltrieren und ihre Belagerungsmaschinen sabotieren.\n\nIch hätte Euch gerne als <Freiwilligen/Freiwillige>.", sourceObjective = "Sabotiert 3 Kriegswagen der Vil'thik im Tal der Ewigen Blüten.", completion = "Unsere Späher berichten, dass mehrere Kriegswagen spektakulär zerstört wurden.\n\nIch vermute, das habe ich Euch zu verdanken.", sourceObjectiveStatus = "unverified-source-field" }
quests[58769] = { id = 58769, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE ME", description = "Ich verstehe jetzt, warum es nur noch so wenige Fae und Seelen gibt. Diese elenden Kreaturen müssen sie sich geholt haben, so wie meinen Mann.\n\nAber ich hole sie zurück. Wenn Ihr wirklich unser neuer Champion seid, dann werdet ihr mir helfen. Zum Wohl des ganzen Ardenwalds.\n\n<Thiernax schnaubt.>\n\nDer Tod konnte uns nicht trennen. Da gebe ich ihn jetzt auf keinen Fall auf.", sourceObjective = "Reitet mit Thiernax den Drust hinterher.", sourceObjectiveStatus = "unverified-source-field" }
quests[58771] = { id = 58771, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ohne Anleitung", description = "Seht Euch hier nur um! Was für ein Durcheinander. Der Gedächtnisraum ist inaktiv und diese \"Verschmähten\" haben ihn übernommen.\n\nWir müssen ihn wiederherstellen, aber ich weiß nicht wie. Dieser Ort wurde vor langer Zeit ohne mein Zutun erbaut.\n\nZum Glück war die vormalige Oberste Schmiedin recht produktiv. Sie hat alles aufgezeichnet! Wenn wir ihre Pläne finden können, werde ich sicher eine Lösung finden. Auch ohne die Hilfe von Mnemis.\n\nSeht Euch um. Hier sind überall Schriftrollen verstreut. Trefft mich in der Nähe des Gedächtnisraums, wenn Ihr gefunden habt, was ich benötige.", sourceObjective = "Findet das Raumhandbuch unter den weggeworfenen Schriftrollen im Gedächtnisraum.", progress = "Habt Ihr die richtige Schriftrolle gefunden?", completion = "Ihr habt sie gefunden! Und obendrein noch andere interessante Folianten. Ich sorge dafür, dass sie ordentlich katalogisiert werden, wenn wir hier fertig sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[58773] = { id = 58773, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der gefangene Dornsprecher", description = "Gut zu wissen, dass der alte Bär mich nicht vergessen hat.\n\nLeider haben die Drust mich auch noch nicht vergessen. Bevor sie hier aufgetaucht sind, war mein Leben im Jenseits äußerst friedlich.\n\nBemüht Euch gar nicht erst, den Käfig zu öffnen. Ihr braucht dafür drei Schlüssel, die von verschiedenen Drustkommandanten hier beschützt werden.\n\nSie sollten in der Nähe sein. Findet sie.", sourceObjective = "Rettet Kivarr aus dem Abendhain im Ardenwald.", progress = "Ich würde Euch gerne helfen, aber wie Ihr sehen könnt... bin ich in einer recht unfreien Lage.", completion = "Die Drust haben mich in diesen Käfig gesperrt und Kivarr weggezerrt. Wenn Ihr mich freilasst, zeige ich Euch, wo sie sind!", sourceObjectiveStatus = "unverified-source-field" }
quests[58775] = { id = 58775, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Treffen mit der Königin", description = "{name}, wir benötigen nur noch ein Teil, um das Emblem des Aufstiegs zu vervollständigen.\n\nVor langer Zeit wurde unser Emblem mit Hilfe der Fae hergestellt. Tief im Ardenwald liegt ein Portal, mit dem sie Seelen zurück in ihre Welten leiten. Es ist eine Quelle großer Macht und der letzte Schlüssel, um das Emblem wiederherzustellen.\n\nSucht die Winterkönigin im Ardenwald auf und tragt ihr unsere Bitte vor. Wir haben bereits Pelagos als unseren Gesandten vorausgeschickt, um Euer Treffen zu arrangieren.", sourceObjective = "Erhaltet eine Audienz bei der Winterkönigin beim Herz des Waldes im Ardenwald.", completion = "Wir haben viel Arbeit vor uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[58776] = { id = 58776, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brutprobleme", description = "Die Aqir vermehren sich schneller, als wir sie ausschalten können. Wenn das so weitergeht, sind wir sehr bald in der Unterzahl.\n\nWir können ihren Vormarsch nur stören, wenn wir direkt ihre Brutstätten angreifen und ihre Eier zerstören. Das ist uns bis jetzt aber nicht gelungen.\n\nDeswegen möchte ich gerne auf Eure Dienste zurückgreifen.\n\nKönnt Ihr uns helfen?", sourceObjective = "Zerstört 6 Aqirgelege in Uldum.", completion = "Die Zerstörung dieser Eier sollte uns genug Zeit geben, um uns neu zu gruppieren, bevor uns die nächste Welle trifft.\n\nDas könnte den Unterschied zwischen Sieg und Niederlage bedeuten.", sourceObjectiveStatus = "unverified-source-field" }
quests[58777] = { id = 58777, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trampelkommando", description = "<Zahra zerstampft eine schleimige, schneckenähnliche Kreatur, als Ihr Euch nähert.>\n\nHabt Ihr das gesehen? Sieht nach Spaß aus, aber es ist kein Spaß mehr, wenn dieses Ungeziefer sich erstmal aus dieser Form weiterentwickelt hat.\n\nSie haben alle Orte, die von den Aqir erobert wurden, geradezu überschwemmt, ernähren sich von unseren Toten und wachsen zu diesen Monstrositäten heran.\n\nWenn Ihr diese Dinger seht, tut der Welt einen Gefallen und zertretet sie.", sourceObjective = "Zerquetscht 8 Aqirlarven in Uldum.", completion = "Eure Stiefel sehen aus, als hättet Ihr eine Menge dieser ekelerregenden Krabbeldinger zertrampelt.\n\nKeine Sorge, das wird schon wieder sauber... irgendwann.", sourceObjectiveStatus = "unverified-source-field" }
quests[58778] = { id = 58778, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopfarbeit", description = "Im Lager hat die Moral in letzter Zeit ziemlich nachgelassen. Es ist schon erstaunlich, wie ein bisschen Ungeziefer die Stimmung herunterziehen kann.\n\nAber ich habe schon einen Plan, wie wir die Truppen wieder aufheitern können. Wir brauchen eine Trophäe!\n\nVersucht, mir einen Kopf einer dieser fetten Kreaturen zu bringen. Die präsentieren wir dann feierlich, sodass alle sehen können, dass mit uns nicht zu spaßen ist! Passt aber bitte auf, dass der Kopf nicht zu arg ramponiert wird, in Ordnung?", sourceObjective = "Besorgt 1 Goliathtrophäen von Goliaths der Aqir in Uldum.", progress = "Zeigt mir, was Ihr habt!", completion = "Meine Güte, der ist ja riesig!\n\nAlso wenn dieser riesige Trophäenkopf die Stimmung der Truppen nicht wieder hebt, dann weiß ich auch nicht weiter!", sourceObjectiveStatus = "unverified-source-field" }
quests[58779] = { id = 58779, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Himmelseroberung", description = "Mal sehen, ob wir noch ein paar dieser Flieger in die Luft bekommen und die Aqir so zurücktreiben. Es ist aber so gut wie unmöglich, zum Obelisken der Sonne zurückzukehren, solange die Luft voll von diesem Ungeziefer ist.\n\nWir müssen sie wohl am Boden etwas ausdünnen, wenn wir die Lufthoheit erlangen wollen.\n\nKönnt Ihr dabei helfen?", sourceObjective = "Tötet 15 fliegende Aqir in Uldum.", completion = "Der Himmel sieht jetzt dank Euch schon viel klarer aus. Hoffentlich reicht das, um unsere Luftflotte erfolgreich abheben zu lassen.\n\nWir danken Euch vielmals für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[58780] = { id = 58780, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herolde des Schwarms", description = "Die Aqir, die unser Lager angegriffen haben, scheinen hauptsächlich Sturmsoldaten gewesen zu sein. Allerdings haben unsere Späher hinter den feindlichen Linien eine andere Art von Kreatur ausgemacht. Sie ist groß, dünn und wirkt gefährliche Leerenmagie.\n\nMein Instinkt sagt mir, dass diese Wesen die Anführer der Invasion sind. Seht sie als Gelegenheitsziele und tötet sie, wo immer Ihr welche seht.\n\nSeid Ihr bereit für diese Aufgabe?", sourceObjective = "Tötet 5 Dominatoren der Aqir in Uldum.", completion = "Sogar eine Hydra stirbt, wenn man ihr nur genug Köpfe abschlägt.\n\nVergesst das nicht in der tobenden Schlacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[58781] = { id = 58781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schrecken der Tiefe", description = "Mit jedem neuen Tag bedrohen die Aqir die Lebensgrundlage der Wüstenwanderer immer mehr. Ich habe aber gehört, das mit ihnen noch größeres Unheil aus der Erde gestiegen ist.\n\nWir haben gute Kämpfer, aber mir graut davor, was passieren könnte, wenn uns einer dieser uralten Schrecken angreift.\n\nIch weiß, dass Ihr im Töten von großen Gegnern Erfahrung habt. Könnt Ihr uns vielleicht helfen?\n\nWir können beim Schutz der Schmiede kaum Unterstützung leisten, wenn uns irgendein uraltes Monster vorher dezimiert.", sourceObjective = "Tötet 3 seltene Aqirgegner in Uldum.", completion = "Dank Euch ist Uldum heute ein Stück sicherer geworden.\n\nIch danke Euch im Namen der Wüstenwanderer.", sourceObjectiveStatus = "unverified-source-field" }
quests[58782] = { id = 58782, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurückgelassen", description = "Der Einfall der Aqir hat viele Wüstenwanderer dazu gezwungen, aus ihren Siedlungen in Uldum zu fliehen. Bei unserer blitzartigen Flucht haben wir viele Dinge zurücklassen müssen.\n\nIch habe gehört, dass ihr diese Bestien direkt angreifen wollt. Wenn Ihr sowieso schon dort seid, könnt Ihr bitte nach Vorräten Ausschau halten, die wir dort zurücklassen mussten?\n\nWas Ihr davon brauchen könnt, dürft Ihr natürlich behalten.", sourceObjective = "Sammelt 3 Vorräte der Wüstenwanderer von befallenen Truhen in Uldum.", progress = "Konntet Ihr etwas finden?", completion = "Ihr habt die Vorräte gefunden? Ich danke dem Himmel!\n\nFür Unvorbereitete können die Wüstennächte verheerend sein. Damit überlebt Ihr da draußen sicher.\n\nDie Wüstenwanderer stehen ihr Eurer Schuld, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[58785] = { id = 58785, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlagen und Schnappen", description = "Die Knochenzähne sind das Rückgrat der Streitkräfte von Maldraxxus. Gut ausgebildete Knochenzähne sind in allen Häusern gefragt.\n\nIch brauche immer neue Knochenzähne zum Ausbilden, aber es kann ziemlich schwierig sein, sie zu sammeln.\n\nBringt mir einige der jüngeren, und ich werde Euch fürstlich belohnen. Lasst Euch sagen, dass Ihr sie möglicherweise erst schwächen müsst, bevor Ihr sie einfangen könnt.", sourceObjective = "Fangt 10 neugeborene Knochenzähne.", progress = "Bringt mir ein paar Knochenzähne!", completion = "Ich bin zufrieden mit Eurer Arbeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[58787] = { id = 58787, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Prüfung des Aufstiegs", description = "Die Verschmähten sind weiterhin eine große Gefahr, und unsere Streitmächte werden schwächer. Wir brauchen die Aufgestiegenen mehr denn je zuvor.\n\nUnsere großzügige Archon hat uns einen Teil der Animavorräte überlassen, damit wir unsere besten Aspiranten aufsteigen lassen und als Verstärkung einsetzen können.\n\nKleia gehört zu den Auserwählten und muss daher nun ihre letzte Prüfung meistern.\n\nDa Pelagos noch nicht für den Aufstieg bereit ist, möchte ich Euch bitten, Kleia bei dieser Prüfung zu unterstützen. Die Prüfung ist sehr anstrengend, und niemand sollte sich ihr allein stellen.\n\nKleia muss nun ihre erste Seele tragen.", sourceObjective = "Trefft Euch mit Kleia im Hof des Jubels.", completion = "Die Verschmähten haben den Hof eingenommen. Sie halten uns von unserer Prüfung fern!", sourceObjectiveStatus = "unverified-source-field" }
quests[58788] = { id = 58788, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rauchbrenner der Führung", description = "Die Verschmähten wollen uns um jeden Preis vom Aufstieg abhalten.\n\nSie blockieren unseren Weg, um unsere Chancen zu zerschlagen, an unseren Ritualen teilzunehmen.\n\nSie haben die Ressourcen gestohlen, die wir für unseren Prüfungsbeginn benötigen. Besiegt sie und holt Euch das Räucherwerk, damit wir diesen Pfad weitergehen können.", sourceObjective = "Sammelt 10 Stücke Räucherwerk der Führung von Streitkräften der Verschmähten ein.", progress = "Jedes Räuchergefäß benötigt viel Räucherwerk. Wir müssen unbedingt genug sammeln.", completion = "Wenn wir dieses Räucherwerk mit unserer eigenen Anima anreichern, führt es uns zu dem Ziel, das jedem von uns vorbestimmt ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[58789] = { id = 58789, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missratene Mentoren", description = "Diese Aspiranten... Wir haben gemeinsam trainiert. Gemeinsam gelernt.\n\nDie Verschmähten haben sie von ihrem Pfad abgebracht und führen sie jetzt ins Verderben.\n\nSie verraten den Pfad. Erledigt die Aufgestiegenen, die diese Kräfte gegen uns einsetzen.", sourceObjective = "Tötet Strategin Palladia und Ausbilder Herus.", completion = "Der Schmerz über all die Aspiranten, die sich bewusst gegen den Willen der Archon entscheiden, vergeht niemals.", sourceObjectiveStatus = "unverified-source-field" }
quests[58790] = { id = 58790, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ab durch den Schleier", description = "Pallessa hat eine Schriftrolle mit den Einzelheiten des Rituals gefunden.\n\nWir müssen unsere Positionen einnehmen und eine Litanei anstimmen, bei der wir mit jedem Wort etwas von unserer Anima aufgeben.\n\nEure Anwesenheit ist wichtig. Ihr müsst das Räucherwerk in den Räuchergefäßen verbrennen, während wir meditieren. Der Rest sollte sich von allein erledigen.", sourceObjective = "Helft Kleia beim Ritus der Führung.", completion = "Wie ich sehe, stammt Ihr von dieser Welt. Kleia sollte sich geehrt fühlen, dass Ihr sie begleitet.", sourceObjectiveStatus = "unverified-source-field" }
quests[58791] = { id = 58791, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Tag wie jeder andere", description = "Die Pflicht der Bringer ist es, Seelen durch den Schleier nach Oribos zu tragen, wo dann über sie gerichtet wird. Anschließend geht es für die Seelen in eines Reiche der Schattenlande.\n\nDiese Seele ist bereit, weiterzuziehen.\n\nWährend dieser Prüfung werdet Ihr den letzten Moment vor dem Tod des Körpers der Seele miterleben.\n\nSobald Ihr bereit seid, werdet Ihr sehen, wie diese Seele den Tod fand.", sourceObjective = "Erlebt Ben Howells letzte Momente.", completion = "Oh, da bist du ja, Liebster. Ich habe dich schon gesucht!", sourceObjectiveStatus = "unverified-source-field" }
quests[58792] = { id = 58792, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Heimat der Seele", description = "Diese Seele ist nicht mehr an die Welt Azeroth gebunden.\n\nKleia muss ihre Pflicht erfüllen und sie nach Oribos bringen, wo die Richterin über sie urteilt.\n\nNehmt diese Vesperglocke. Sobald Ihr bereit seid, ruft sie einen Aufgestiegenen, der Euch durch den Schleier hindurch nach Oribos zurückbringt.\n\nGeht und dient.", sourceObjective = "Läutet die Vesperglocke des Schleierflugs, um nach Oribos zu reisen, und werdet Zeuge von Ben Howells Urteil.", progress = "Es ist die Pflicht der Kyrianer, die Seelen nach Oribos überzusetzen.", completion = "Ich... brauche etwas Zeit, um das aufzubereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[58793] = { id = 58793, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vertrauen durch die Dunkelheit hindurch", description = "Diese Dürre ist... so viel größer, als ich gedacht hatte.\n\nWarum hat niemand uns etwas davon gesagt?\n\nDie Bürde dieses Wissens wiegt schwer... Tragen wir Seelen zu ewigen Qualen?\n\nWir müssen nach Hause zurückkehren.", sourceObjective = "Kehrt zu Adrestes in die Elysische Feste zurück.", completion = "Ich bin froh, dass Kleia erfolgreich zu uns zurückgekehrt ist. Sie hinterfragt zwar vieles, aber ihre Pflichten nimmt sie sehr ernst.\n\nWenn ich das doch nur von allen Aspiranten sagen könnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[58794] = { id = 58794, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Westen spielt die Musik", description = "Ich habe in letzter Zeit eine Menge Tauralusleichen gefunden, und ich weiß, das liegt alles an diesen Knochenzähnen, die Caleesy so sehr liebt!\n\nIch habe den Verantwortlichen für das Gemetzel westlich von hier entdeckt. Beseitigt ihn!\n\nUnd erwähnt das Caleesy gegenüber nicht!", sourceObjective = "Tötet den satten Sägezahn.", completion = "Gute Arbeit, aber erzählt Caleesy nichts davon.", sourceObjectiveStatus = "unverified-source-field" }
quests[58795] = { id = 58795, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufgestiegen", description = "Nachdem sie ihre Prüfungen gemeistert haben, beginnt für unsere Aspiranten jetzt das nächste Kapitel in ihrem Leben nach dem Tod.\n\nSie haben sich über viele Äonen im Training und in der Läuterung bewiesen und ihren Aufstieg redlich verdient.\n\nWährend die Aspiranten aufgerufen werden, bitte ich Euch und Pelagos, zu helfen, indem Ihr sie hinaufgeleitet. Dies ist eine Tradition, die wir schon ewig praktizieren und die das Band, das wir teilen, weiter stärkt.", sourceObjective = "Helft Pelagos bei der Aufstiegszeremonie.", completion = "Die Verschmähten, ausgerechnet jetzt?\n\nDas ist ein Großangriff!", sourceObjectiveStatus = "unverified-source-field" }
quests[58796] = { id = 58796, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ansturm der Verschmähten", description = "Dieser schändliche Verrat der Loyalität bleibt nicht ungesühnt.\n\nAber während die Paragons die eigentliche Stadt verteidigen, müssen wir die Elysische Feste beschützen.\n\nIch bin schwer verwundet... aber ich werde durchhalten und mich mit Pelagos um die Überlebenden kümmern. Ihr müsst dabei helfen, diesen Angriff zurückzuschlagen!", sourceObjective = "Schlagt die Invasion der Verschmähten zurück.", progress = "Devos... Sie geht zu weit.", completion = "Und so wendet sich das Blatt in der Schlacht.\n\nDie Elysische Feste mag jetzt zwar in Sicherheit sein, aber die Spitzen brauchen weiter unsere Hilfe!", sourceObjectiveStatus = "unverified-source-field" }
quests[58797] = { id = 58797, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Feuer der Prüfungen geschmiedet", description = "{name}, <mein treuer Freund/meine treue Freundin>.\n\nSeit einiger Zeit fühle ich jetzt schon diese starke Verbundenheit zwischen uns. Alles begann mit meiner großen Begeisterung, als Ihr Euch entschlossen habt, uns hier in der Bastion zu unterstützen... Ich wusste von Anfang an, Ihr wärt ein großer Gewinn.\n\nMit jeder neuen Prüfung wurde das Band zwischen uns stärker. Ohne Euch wäre ich vielleicht so wie Achillon ein Opfer meines neu gefundenen Wissens geworden.\n\nIch möchte unser Band noch weiter festigen. Es wäre mir eine Ehre, mit Euch das Seelenband einzugehen.", sourceObjective = "Schließt das Ritual der Seelenbindung mit Kleia ab.", completion = "Ihr, ich und unser lieber Pelagos.\n\nIch glaube nicht, dass es irgendwo ein besseres Team gibt.", sourceObjectiveStatus = "unverified-source-field" }
quests[58798] = { id = 58798, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Spitzen des Aufstiegs", description = "Unsere Aufgabe ist noch nicht vollbracht.\n\nWir haben vielleicht die Verschmähten hier in der Elysischen Feste zurückgeschlagen, aber das war nur ein Ablenkungsmanöver, um unsere Streitkräfte aufzuteilen.\n\nDie Archon und die Paragons selbst erobern jetzt die Spitzen zurück.\n\nWir müssen ihnen in dieser dunklen Stunde beistehen!", sourceObjective = "Tötet Devos, Paragon des Zweifels, in den Spitzen des Aufstiegs.", completion = "Wir haben viel aus diesem Angriff gelernt. Die Archon wird mit den verbleibenden Paragons zusammenkommen, um über Bedrohung durch die Verschmähten zu beratschlagen.\n\nWir werden Euch rufen lassen, wenn wir Euch brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58799] = { id = 58799, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Direktive des Obersten", description = "Alle Zenturionen wurden erschaffen, um den Kyrianern zu dienen.\n\nDass sie jetzt GEGEN mich arbeiten, den OBERSTEN Schmied, ist eine Beleidigung für alle Zenturionen in der Bastion. Seht sie Euch nur an! Prätoren! Goliaths! Alle in... LILA!\n\nIch erteile Euch hiermit die Erlaubnis, ja, ich befehle Euch ausdrücklich, ihre Kerne zu extrahieren. Ich werde sie einem angemessenen Zweck zuführen: Ich werde ihre Anima wiedergewinnen, um den Gedächtnisraum mit Energie zu versorgen.\n\nIch kann neue bauen, Ihr braucht also kein Mitleid mit ihnen zu haben.", sourceObjective = "Sammelt 12 Zenturionenkerne.", progress = "Habt Ihr die Kerne?", completion = "Ausgezeichnet. Ihre Anima wird einem besseren Zweck zugeführt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[58800] = { id = 58800, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Gedächtnisraum", description = "<Mikanikos untersucht die Schriftrolle, die Ihr für ihn wiedergefunden habt.>\n\nAch ja, richtig.\n\nSeelenspiegel und Gedächtnisraum sind miteinander verbunden. Wenn wir den Spiegeln wieder Anima verleihen, sollte das den Gedächtnisraum wieder voll funktionsfähig machen. Zum Glück sollten die Kerne, die Ihr mitgebracht habt, dafür ausreichen.\n\nJetzt muss ich nur noch Leitungen aktivieren. Kinderspiel!\n\nNun? Na los. Ihr wisst doch, wie man sie benutzt, oder?", sourceObjective = "Benutzt die Animaleitungen, um den Gedächtnisraum wiederherzustellen.", progress = "Ich warte auf das Summen der Anima, ja.", completion = "Ich liebe das Summen von Anima. Es ist lange her, seit ich es in solchem Überfluss gehört habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[58801] = { id = 58801, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eintritt in die Leere", description = "<Als Ihr Euch dem Götzen nähert, scheinen die dunklen Splitter, die Ihr bei Euch tragt, mit Eurer Hand zu verschmelzen. Sofort werdet Ihr von unaussprechlicher Qual übermannt. Diese weicht schnell Gefühlen von Freude, Gleichmut und einem überwältigenden Verlangen... zu töten.\n\nEine zischelnde Stimme dringt in Euren Geist ein.>\n\n<Mein treuer Diener/Meine treue Dienerin>, ich werde Euch einen winzigen Vorgeschmack meiner unvorstellbaren Macht gewähren. Als Gegenleistung verlange ich lediglich die Erfüllung einer einfachen Aufgabe. Tötet alle, die sich mir entgegenstellen, und verschont niemanden. Enttäuscht mich nicht...", sourceObjective = "Opfert N'Zoth 10 Spielercharaktere, ohne zu sterben oder die Form des Leerengeists zu verlassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58802] = { id = 58802, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das unglaubliche Ei", description = "<Die Aqir waren wohl gerade dabei, dieses Ei mit Leerenmagie zu ermächtigen.\n\nEs sieht nicht so aus, als ob es bald schlüpfen wird, also dürfte es ungefährlich sein, es zu studieren und herauszufinden, was sie damit vorhatten.\n\nJemand in der Forscherliga könnte sich dafür interessieren.>", sourceObjective = "Bringt das leerenberührte Ei zu H'partho Ardoros in Ramkahen.", completion = "Faszinierend! Ihr sagt, dass die Aqir versucht haben, dieses Ei zu ermächtigen?\n\nIhr habt das Richtige getan, indem Ihr das Ei in meine Obhut gegeben habt. Denkt nur an all die Wunder, die wir entdecken werden, wenn es ausschlüpft!\n\nIhr seht besorgt aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[58803] = { id = 58803, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie ein Ei dem anderen", description = "Keine Sorge, ich bin sicher, dass beim Schlüpfen dieser Kreatur nichts Schlimmes passieren wird. Schließlich können die Aqir nicht böse geboren werden, oder?\n\nNatürlich haben wir keine Ahnung, wie man sich um solch ein Ei kümmert. Ihr müsst ein wenig für mich nachforschen.\n\nGeht zurück zu den Aqirschwärmen und seht, ob Ihr dort ähnliche Eier wie dieses findet. Wenn wir beobachten können, wie man damit umgeht, könnten wir diese Erkenntnisse vielleicht hier anwenden.", sourceObjective = "Untersucht 7 leerenberührte Eier in Uldum.", completion = "Die Eier sind geschlüpft, während Ihr sie untersucht habt, sagt Ihr?\n\nDas ist bedauerlich, aber wenigstens seid Ihr unversehrt zurückgekommen!\n\nIch gehe diese Notizen durch und versuche, ein wenig mehr über unseren kleinen Freund hier zu erfahren. Vielleicht können wir ja einen Weg finden, das Schlüpfen zu beschleunigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58804] = { id = 58804, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brütende Leere", description = "Nun, eins ist sicher, was dieses Ei angeht: Es benötigt viel Leerenenergie, um sich zu entwickeln.\n\nDa können wir ja von Glück reden, dass gerade ein Alter Gott Azeroth angreift, stimmt's?\n\nFindet Ihr nicht? Oh...\n\nJedenfalls sollte dort, wo N'Zoths Diener sich befinden, jede Menge Leerenenergie sein. Ihr solltet losziehen und etwas davon besorgen.", sourceObjective = "Sammelt 10 kristallisierte Leere in Gebieten, die von N'Zoths Streitkräften angegriffen werden.", progress = "Habt Ihr eine verlässliche Quelle für Leerenenergie gefunden?", completion = "Großartig! Die von diesen Kristallen ausgehende Leerenenergie ist perfekt, um das Ei zu bebrüten.\n\nKeine Sorge, ich bin sicher, das Herumtragen dieser Kristalle hat keinerlei Nebenwirkungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58805] = { id = 58805, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Behüten und brüten", description = "Dem Ei geht es gut. Aber wir werden für seine gesunde Entwicklung mehr dieser Leerenkristalle brauchen.\n\nKönnt Ihr mir noch mehr davon bringen?", sourceObjective = "Sammelt 10 kristallisierte Leere in Gebieten, die von N'Zoths Streitkräften angegriffen werden.", progress = "Habt Ihr weitere Leerenkristalle mitgebracht?", completion = "Ja, das sieht doch gut aus.\n\nIch werde mich weiter um das Ei kümmern und Euch über seinen Fortschritt auf dem Laufenden halten.", sourceObjectiveStatus = "unverified-source-field" }
quests[58806] = { id = 58806, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sonnenwärme", description = "Die Wüstennächte in Uldum können sehr kalt werden. Ich glaube kaum, dass unser Ei diese Temperaturen schadlos übersteht.\n\nDie Amathet im Osten haben die Nutzung der Sonnenenergie offenbar perfektioniert. Wenn wir ihr Wissen hätten, könnten wir damit dem Ei sicher ein warmes und gemütliches Nestchen bauen.\n\nSeht Euch um, ob Ihr etwas von Nutzen finden könnt.", sourceObjective = "Besorgt einen Sonnensammler der Amathet in Uldum.", progress = "Habt Ihr bei den Amathet etwas gefunden?", completion = "Ihr habt einen Sonnensammler gefunden? Wundervoll!\n\nAb jetzt ist unser Ei in den kalten Nächten wohlig warm geschützt.", sourceObjectiveStatus = "unverified-source-field" }
quests[58807] = { id = 58807, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gut eingepackt", description = "Mir ist aufgefallen, dass dieses Ei, anders als in einem Aqirbau üblich, keine schützenden Spinnweben hat. \n\nIch glaube, diese Spinnweben sichern das Ei und wären deswegen sehr nützlich für uns, falls Ihr welche findet.\n\nSchaut Euch bei Euren Kämpfen gegen die Insekten um, ob Ihr solche Spinnweben auftreiben könnt. Damit bauen wir unserem Ei einen schönen Kokon.", sourceObjective = "Sammelt 30 Stücke Aqirspinnweben von Zauberwirkern der Aqir in Uldum.", progress = "Habt Ihr passende Spinnweben gefunden?", completion = "Oh, die sind aber wirklich sehr klebrig. Aber es sollte funktionieren.\n\nGebt mir einen Moment, unser kleines Kerlchen schön einzupacken.", sourceObjectiveStatus = "unverified-source-field" }
quests[58808] = { id = 58808, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Bern eingeschlossen", description = "Wisst Ihr, wer wahrscheinlich genau Bescheid weiß, wie wir dieses Ei richtig ausbrüten können? Die Mantis!\n\nNatürlich sind sie eher damit beschäftigt, uns zu zerfleischen, als dass sie Zeit für einen Brutkurs hätten, aber es gibt vielleicht eine andere Möglichkeit, ihr Wissen zu nutzen!\n\nVielleicht können wir eine ihrer Inkubationskammern verwenden. So brüten wir das Ei sicher schneller aus!\n\nWenn Ihr eine für mich finden und markieren könntet, würde ich sie von dort abholen lassen.", sourceObjective = "Markiert einen Berninkubator im Tal der Ewigen Blüten, damit H'partho sie abholen lassen kann.", completion = "Perfekt! \n\nDas wird unserem Ei ein schönes gemütliches Zuhause sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[58809] = { id = 58809, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elektrisierende Technik", description = "Ich habe Geschichten gehört, dass die Mogu Blitze nutzen, um das Wachstum ihrer Wolkenschlangen zu beschleunigen. Vielleicht können wir diese Technik auch bei unserem Aqirfreund anwenden?\n\nEs gibt nur einen Weg, es herauszufinden! Geht in das Tal der Ewigen Blüten und versucht, die richtigen Teile zu finden, mit deren Hilfe wir selbst Blitzableiter herstellen können.\n\nWenn es genauso wie bei den Wolkenschlangen funktioniert, dann können wir den Brutvorgang immens beschleunigen.", sourceObjective = "Sammelt 8 Blitzableiterteile im Tal der Ewigen Blüten.", progress = "Habt Ihr die richtigen Komponenten zusammenbekommen?", completion = "Ich hoffe, die Mogu haben Euch nicht zu viel Ärger gemacht.\n\nEs wird sich alles auszahlen, wenn unser Schützling hier schlüpft.", sourceObjectiveStatus = "unverified-source-field" }
quests[58810] = { id = 58810, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie aus dem Ei gepellt", description = "Anscheinend ist unser Ei bereit zu schlüpfen! Das ist so aufregend!\n\nKommt, lasst uns unseren neuen kleinen Freund auf dieser Welt willkommen heißen.", sourceObjective = "Beobachtet, wie das Ei der Aqir in Ramkahen schlüpft.", completion = "Ist er nicht wunderschön?\n\nEs dauert natürlich noch, bis er voll ausgewachsen ist, aber er ist doch schon jetzt ein beeindruckendes Bürschchen!", sourceObjectiveStatus = "unverified-source-field" }
quests[58811] = { id = 58811, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgewogene Ernährung", description = "Jetzt, wo die Larve geschlüpft ist, müssen wir herausfinden, welche Nahrung für seine gesunde Entwicklung das Richtige ist.\n\nMan sollte meinen, dass die Aqir Fleischfresser sind, aber bis jetzt habe ich nur gesehen, dass sie... naja... uns fressen.\n\nNatürlich können wir unseren Kleinen hier nicht mit Leuten füttern. Wir brauchen eine Alternative. Vielleicht funktioniert es mit Tierfleisch?", sourceObjective = "Sammelt 12 Fleischbrocken von Wildtieren in Uldum und dem Tal der Ewigen Blüten.", progress = "Er sieht hungrig aus. Ich hoffe, Ihr habt etwas zu futtern dabei.", completion = "Tierfleisch scheint ihm nicht zu schmecken.\n\nFür den Moment sollte es genügen. Versuchen wir es später mit etwas anderem.", sourceObjectiveStatus = "unverified-source-field" }
quests[58812] = { id = 58812, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fleischalternativen", description = "In der Natur ist es durchaus üblich, dass Insekten sich von ihren eigenen Artgenossen ernähren. Das könnte natürlich auch auf die Aqir zutreffen.\n\nKönnt Ihr ein bisschen Fleisch von Aqir oder Mantis besorgen? Vielleicht bekommt das dem Gaumen unseres Freundes hier besser.", sourceObjective = "Sammelt 12 Brocken Insektenfleisch von Aqir, Mantis oder anderen Insekten in Uldum oder dem Tal der Ewigen Blüten.", progress = "Ich hoffe sehr, dass das funktioniert.", completion = "Armes Ding. Das Insektenfleisch ist ihm nicht gut bekommen.\n\nMorgen versuchen wir etwas anderes.", sourceObjectiveStatus = "unverified-source-field" }
quests[58813] = { id = 58813, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Faulige Filets", description = "Hm, also mir kam der Gedanke, dass durch diese Kreatur ja Leerenenergie fließt und sie deshalb vielleicht eher... verderbte Nahrung bevorzugt.\n\nIch meine damit natürlich die Diener von N'Zoth.\n\nEs ist natürlich weit hergeholt, aber sicher einen Versuch wert.", sourceObjective = "Sammelt 12 Brocken verderbtes Fleisch von Kreaturen in Gebieten, die von N'Zoths Dienern heimgesucht werden.", completion = "Sehr gut! Der Kleine hat alles aufgegessen!\n\nDas ist wirklich praktisch. Ich wollte auf keinen Fall Phaoris fragen, ob er frische Tol'virleichen im Angebot hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[58816] = { id = 58816, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinter der Bühne", description = "Das Nächste, was wir brauchen, um das Gefäß vorzubereiten, sind ein paar Blumen namens Schleier der Nacht.\n\nWir verwenden diese Blumen für unsere Zeremonien, aber seit der Dürre wurden sie nur noch als Requisiten für das Schauspiel verwendet. Am Sternseeamphitheater gibt es sicherlich welche hinter der Bühne.\n\nIch wette, dass sich Mondbeere dort aufhält und für den nächsten Auftritt probt. Dass ich mich damit an ihr rächen kann ist eine nette Dreingabe für mich.\n\n<Weidenblüte grinst hämisch.>", sourceObjective = "Besorgt einen Blumenkranz aus Nachtschleiern aus dem Bereich hinter der Bühne des Sternseeamphitheaters.", progress = "Habt Ihr die Blumen?", completion = "Mission erfüllt! Das wird ein großer Spaß. Ah, süße Rache.", sourceObjectiveStatus = "unverified-source-field" }
quests[58817] = { id = 58817, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Actionfiguren", description = "Unser kleiner Freund langweilt sich hier wirklich sehr. Wir müssen etwas finden, mit dem er sich beschäftigen kann.\n\nNur eine glückliche Larve ist auch eine gesunde Larve!\n\nDie Amathet haben soweit ich weiß Götzenfiguren zur Verehrung ihrer Götter. Die sind mit Sicherheit wunderbar als Spielzeuge für unseren Schützling geeignet. Seht Euch mal um, ob Ihr welche finden könnt.", sourceObjective = "Sammelt 6 Amathetfiguren von Amathetkreaturen in Uldum.", progress = "Habt Ihr passendes Spielzeug gefunden?", completion = "Seht nur, wie sehr er sich über sein neues Spielzeug freut!", sourceObjectiveStatus = "unverified-source-field" }
quests[58818] = { id = 58818, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krabbelgruppe", description = "Bilde ich mir das nur ein, oder sieht unser kleiner Freund hier sehr einsam aus? Die Aqir sind sicher soziale Kreaturen, sie leben schließlich alle zusammen in einem Bau und das alles. Es ist mit Sicherheit nicht schön für ihn, so allein zu sein.\n\nVielleicht könntet Ihr ja ein paar Spielkameraden für ihn auftreiben. Aber nichts Großes oder Furchteinflößendes. Vielleicht wäre ein kleiner Skarabäus ein geeigneter, aber ungefährlicher Freund.\n\nWas meint Ihr?", sourceObjective = "Fangt 5 sanftmütige Sandsteinjungtiere in Uldum.", completion = "Seht nur! Sie spielen! Zumindest sieht es danach aus.\n\nEgal, nichts geht über ein paar gute Freunde, wenn man so ein kleiner Racker ist. Gut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[58820] = { id = 58820, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bindungen der Fleischformung", description = "Das sind die Bindungen der Fleischformung! Mithilfe dieser Bindungen hat der Primus Fleisch und Knochen von Maldraxxus formen können.\n\nWir müssen sie an ihren angestammten Platz zurückbringen, damit ihre Kraft uns alle stärkt.", sourceObjective = "Platziert die Bindungen der Fleischformung auf der Statue des Primus.", completion = "Ich kann ihre Kraft spüren. Vielleicht liefern sie uns den entscheidenden Vorteil.", sourceObjectiveStatus = "unverified-source-field" }
quests[58821] = { id = 58821, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glorreiche Unterfangen", description = "Draka mag ihre Treue vergessen haben, doch ich werde meine Mission erfüllen.\n\nMein Gegner, der Lich Mor'Bitan, verbirgt sich im Haus der Rituale. Aus irgendeinem Grund lauern seine Untergebenen in diesem Sumpf.\n\nWir wissen nicht, was sie dort machen, doch meine Ergebenen haben Mor'Bitans stellvertretenden Kommandanten entdeckt, Mephiles den Loyalen. Er kennt die Antwort.\n\nErgreift ihn für mich. Wenn Ihr ihn habt, erschlagt seine Artgenossen. Schwächt ihn.\n\nIch werde meine Basis für sein Verhör vorbereiten.", sourceObjective = "Entführt Mephiles den Loyalen und tötet dann 6 morbide Jünger, um ihn einzuschüchtern.", completion = "Eine einfache Aufgabe für solch einen berühmten Helden.", sourceObjectiveStatus = "unverified-source-field" }
quests[58825] = { id = 58825, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supergelée", description = "Meine Freunde beim Goldenen Lotus haben mir einige interessante Dinge über den neuen Mantisschwarm erzählt. Er hat offenbar eine Art konzentriertes Gelée Royale entwickelt, das das Wachstum der frisch geschlüpften Mantis deutlich beschleunigt.\n\nWenn dieses Gelée bei den Mantis wirkt, dann müsste es doch logischerweise auch bei den Aqir wirken!\n\nVersucht, eine ausreichende Menge dieses Gelées zu besorgen, dann werden wir sehen, ob es unserer Larve beim Wachsen hilft.", sourceObjective = "Sammelt 8 konzentriertes Gelée Royale im Tal der Ewigen Blüten.", completion = "Seht nur, wie er es runterstürzt! \n\nHoffentlich haut das hin.", sourceObjectiveStatus = "unverified-source-field" }
quests[58826] = { id = 58826, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutsnack", description = "Ich habe erfahren, dass ein Moguklan namens Dokani es geschafft hat, Lebenskraft in einer Substanz namens Anima zu sammeln.\n\nWenn dieses Zeug wirklich kondensierte Lebenskraft in flüssiger Form ist, wird es bei der Aufzucht von Aqirlarven sicher spektakuläre Dienste leisten.\n\nVielleicht könnt Ihr mir etwas von dieser Anima in einer nutzbaren Form besorgen. Mal sehen, ob unser kleiner Freund das mag!", sourceObjective = "Sammelt 8 Phiolen mit geläuterter Anima von Mogu der Dokani im Tal der Ewigen Blüten.", progress = "Seid Ihr mit der Anima zurück?", completion = "Es scheint ihm wirklich zu schmecken! Der Blutgeschmack macht wahrscheinlich den Unterschied.\n\nIch werde genau beobachten, wie die Anima sein Wachstum beeinflusst.", sourceObjectiveStatus = "unverified-source-field" }
quests[58829] = { id = 58829, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "So schnell werden sie groß", description = "Seht nur! Unser kleiner Larvenfreund ist in das Puppenstadium übergegangen! \n\nWartet... Es sieht so aus, als wäre er bereit, herauszukommen.\n\nNa los, helft ihm schon!", sourceObjective = "Helft der Aqirlarve in Ramkahen, sich aus ihrem Kokon zu befreien.", completion = "Glückwunsch! Unsere kleine Larve ist jetzt ein voll entwickeltes Aqirjungtier!\n\nIhr seid sicher sehr stolz.", sourceObjectiveStatus = "unverified-source-field" }
quests[58830] = { id = 58830, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aqirinstinkte", description = "Als ich die Kämpfe der Aqir gegen die Wüstenwanderer beobachtet habe, ist mir aufgefallen, wie sich frisch geschlüpfte Aqir sofort in den Kampf stürzen. Offenbar haben sie einen angeborenen Kampfinstinkt.\n\nUnser Schützling sollte das üben, natürlich unter Eurer Aufsicht. Nehmt ihn mit und zeigt ihm, wie man unsere Gegner bekämpft.\n\nEr kann vielleicht noch nicht allzu lange kämpfen, also ruft ihn erst, wenn ihr fürs Training bereit seid.\n\nWenn wir Glück haben, sieht er uns als Teil seines Schwarms an.", sourceObjective = "Benutzt H'parthos Pfeife, um Eurer Aqirjungtier zu rufen, und bekämpft mit ihm Gegner in Uldum oder im Tal der Ewigen Blüten. Wenn Ihr stärkere und seltenere Gegner bekämpft, wird Eurer Jungtier schneller wachsen.", completion = "Das war sicher ein aufregender Tag für unser kleines Jungtier.\n\nEs wird sich jetzt ausruhen müssen, aber morgen geht es sicher weiter!", sourceObjectiveStatus = "unverified-source-field" }
quests[58831] = { id = 58831, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feinschliff der Instinkte", description = "Es sieht so aus, als ob unser kleiner Freund bereit ist und sich schon auf die nächsten Kampfübungen freut.\n\nWärt Ihr so nett, ihm zu zeigen, wo es langgeht?", sourceObjective = "Benutzt H'parthos Pfeife, um Eurer Aqirjungtier zu rufen, und bekämpft mit ihm Gegner in Uldum oder im Tal der Ewigen Blüten. Wenn Ihr stärkere und seltenere Gegner bekämpft, wird Eurer Jungtier schneller wachsen.", completion = "Der Kleine ist nach Euren Abenteuern ziemlich geschafft.\n\nKeine Sorge, ich päppele ihn auf, während Ihr Uldum rettet.", sourceObjectiveStatus = "unverified-source-field" }
quests[58832] = { id = 58832, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trinkel gemäßigt", description = "<Auf dem Zettel finden sich Kritzeleien zu einem Plan, Seidenschreiterlarven zu stehlen und sie zu kochen.\n\nUnterzeichnet ist er von jemandem namens Trinkel.>", sourceObjective = "Tötet Trinkel den Seidenfresser.", completion = "Widerwärtiger Spriggan!", sourceObjectiveStatus = "unverified-source-field" }
quests[58833] = { id = 58833, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu den Waffen", sourceObjective = "Trefft Draka und ihre Verbündeten im Haus der Rituale.", completion = "Der Zufall hat uns zusammengeführt, aber jetzt kämpfen wir wie eine Einheit.\n\nUnser heutiger Sieg wird ein Sieg für alle Maldraxxi sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[58842] = { id = 58842, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kuratorin", description = "Ich habe der Kuratorin die Aufgabe übertragen, das Medaillon der Habsucht zurückzubeschaffen.\n\nDoch seit ihrer Rückkehr aus dem Schlund ist ihr Geist ein wenig... durcheinander. Seid nett, ja?\n\nIch bitte Euch, dass Ihr sie bei der Suche unterstützt. Sie ist bei der Gruft der Vergessenen.", sourceObjective = "Trefft Euch mit der Kuratorin bei der Gruft der Vergessenen.", completion = "Wir müssen diese Spiegelscherben vor Denathrius' Lakaien bekommen.\n\nDas ist der einzige Weg, um Zugang zu der Gruft zu erlangen, in der ich mein Medaillon verborgen habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[58843] = { id = 58843, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kammer der Archon", description = "Hinter mir ist der Eingang zur Kammer der Archon. Wie Ihr seht, ist er gegen jeglichen unbefugten Zutritt geschützt.\n\nUm offiziellen Zutritt zu erhalten, platziert Ihr die von Euch gesammelten Opfergaben vor den Wächtern. Dann könnt Ihr Euch den Inhalt der Kammer nach Belieben ansehen.\n\nDenkt daran, dass dieser Zutritt unter den Verschmähten begehrt ist und das einzige Ziel ihrer Anstrengungen hier ist. Ich rate Euch, auf den Kampf vorbereitet zu sein.", sourceObjective = "Verschafft Euch Einlass in die Kammer der Archon.", completion = "Es freut mich, Euch kennenzulernen. Die Kammer hat schon seit einiger Zeit keine Besucher mehr gesehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58844] = { id = 58844, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vor dem Morgenrot", description = "Wir benötigen den Rest unserer Streitkräfte für den Sieg.\n\nRuft sie alle zusammen. Die Hüter, Bringer, Zenturionen und Sammler. Sagt ihnen, dass ihre Archon sie braucht.\n\nDie Paragons werden einen Stützpunkt am Hof des Jubels für den letzten Angriff vorbereiten.", sourceObjective = "Versammelt die Hüter, Bringer, Zenturionen und Sammler.", completion = "Ich hoffe, Ihr seid vorbereitet, Schlundgänger.", sourceObjectiveStatus = "unverified-source-field" }
quests[58846] = { id = 58846, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das übergeordnete Wohl", description = "Die Verschmähten sind unsere einstigen Verbündeten... unsere einstigen Waffenbrüder und -schwestern. Aber wir müssen es zu Ende bringen.\n\nWir greifen sie von allen Seiten an. Kämpft tapfer, aber vergesst nicht, dass Lysonia unser eigentliches Ziel ist. Sollte sie unbesiegt bleiben, wird sie weiter für ihre Sache rekrutieren.\n\nFolgt dem Pfad, {name}.", sourceObjective = "Besiegt Lysonia.", completion = "Endlich sind wir siegreich, dank Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[58847] = { id = 58847, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kyrestias Gunst", description = "Ich erinnere mich an diese spezielle Seele... Uther. Devos brachte ihn vor einer Weile zu uns. Sie brachte vor, dass seine Seele eine Verbindung zum Schlund hätte.\n\nSie nahm ihn unter ihre Fittiche und ließ ihn aufsteigen, bevor er bereit war. Neben Lysonia wurde er zu ihrem vertrautesten Diener.\n\nEr mag von einem Sinneswandel sprechen, aber wir werden sehen. Stellt ihn unter Bewachung. Die Archon will vielleicht, dass er bleibt, aber ich gehe kein Risiko ein, wenn jemand so... gebrochen ist.", sourceObjective = "Begleitet Uther.", completion = "Mögen Thenios' Mühen von Erfolg gekrönt werden. In all meinen Äonen habe ich noch nie solch eine gebrochene Seele erlebt.", sourceObjectiveStatus = "unverified-source-field" }
quests[58854] = { id = 58854, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versammelt die Paragons", description = "Wir haben die Verschmähten überall besiegt. Die gerettet, die noch zu retten waren. Haben sie aus den Tempeln unserer gesegneten Archon vertrieben. Nun bleibt nur noch einer.\n\nDer Tempel der Loyalität.\n\nLysonia ist seit ihrer Niederlage in Verzweiflung geraten. Sie hat alles aufgegeben, was wir versuchen, aufrechtzuerhalten, indem sie sich dem Schlund hingegeben hat. Sie hat ihre eifrigsten Anhänger am Tempel versammelt und weiß, dass wir kommen werden.\n\nWir brauchen die Paragons, um dies zu beenden. Ruft sie herbei.", sourceObjective = "Ruft die Paragons herbei, um sie in den Kampf zu schicken.", progress = "Ohne die Paragons können wir gegen Lysonia nicht bestehen.", completion = "Die Paragons stehen bereit, und wir müssen die restlichen Streitkräfte versammeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[58856] = { id = 58856, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wen führt Ihr hinters Licht?", description = "Wir können das Ritual nicht ohne einen ganz besonderen Gast durchführen. Es handelt sich um Larvi, die Seidenschreiterlarve, meinen besten Freund.\n\nLeider haben die boshaften Spriggans ihn entführt! Und was noch schlimmer ist, sie verzaubern das, was sie stehlen, damit niemand es zurückholen kann!\n\nDie Spriggans haben häufig Trickserpulver dabei. Wenn Ihr etwas von diesem Zeug besorgen könnt, kann ich ihre Illusionen rückgängig machen und Larvi retten.", sourceObjective = "Erbeutet Sicheldorntrickserpulver von Sicheldornspriggans, um die Illusionen von verdächtigen Objekten zu bannen und Larvi zu finden.", completion = "Wir haben ihn gefunden!", sourceObjectiveStatus = "unverified-source-field" }
quests[58857] = { id = 58857, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Samen los!", description = "Ich glaube, wir haben ein Problem. Die Samen von dieser Wurzel zu pflücken, muss ein paar vergrabene Gorm geweckt haben! Das ist nicht gut!\n\nHaltet Euch an mir fest! Ich fliege uns hier heraus, aber wir müssen die Gorm aufhalten, bevor sie die Verteidigung der hiesigen Vorkai überrennen!", sourceObjective = "Haltet die Gorm davon ab, den Gormnestschutzwall zu überrennen und in den Rest des Ardenwalds vorzustoßen!", progress = "Das ist unfassbar. Blaue Samen, rote Samen, fliegende Feen!", completion = "Also gut, ich glaube, es ist endlich alles bereit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[58858] = { id = 58858, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr faulige Filets", description = "Unser kleiner Freund wird schon wieder hungrig.\n\nKönnt Ihr ihm schnell etwas zu Essen besorgen?", sourceObjective = "Sammelt 12 Brocken verderbtes Fleisch von Kreaturen in Gebieten, die von N'Zoths Dienern heimgesucht werden.", completion = "Exzellent! Damit wird er sicher groß und stark!\n\nHoffentlich stehen dann nicht wir auf seinem Speiseplan!", sourceObjectiveStatus = "unverified-source-field" }
quests[58859] = { id = 58859, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jemand seiner Größe", description = "Es ist zweifelsohne ein gutes Training für Euer Jungtier, dass Ihr es bei Euren Kämpfen dabeihabt, aber manchmal sollte es auch allein gegen Gegner seiner Größe kämpfen.\n\nIch kenne einen solchen Gegner in der Nähe, der die Amathet in der Nähe des Obelisken der Sterne beobachtet. Ihr solltet ihn ausfindig machen.", sourceObjective = "Besiegt Retinus den Sucher in einem Haustierkampf mit Eurem Schattendornjungtier in Eurer Gruppe.", completion = "Dieser Kampf war sicher aufregend!\n\nWir sollten morgen versuchen, weitere Trainingskämpfe zu organisieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[58860] = { id = 58860, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großer böser Käfer", description = "Es würde unserem Jungtier sicher guttun, wenn er gegen einen anderen Aqir antreten würde. Dann kann es lernen, was seine Art alles so draufhat.\n\nIch habe einen Gegner gefunden, der einen guten Kampf liefern könnte.", sourceObjective = "Besiegt den Sandkrabbler der Aqir in einem Haustierkampf mit Eurem Schattendornjungtier in Eurer Gruppe.", completion = "Unser kleines Jungtier scheint im Kampf ein richtig harter Brocken zu sein!\n\nDas ist jetzt aber genug Training für heute.", sourceObjectiveStatus = "unverified-source-field" }
quests[58861] = { id = 58861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mantismeucheln", description = "Die Beobachtung der Kampftechniken der Mantis könnte sich als hilfreich erweisen, um unserem Jungtier neue Wege aufzuzeigen, die natürlichen Waffen eines Insekts einzusetzen.\n\nIch habe im Tal der Ewigen Blüten einen Mantis als Gegner ausgemacht, der perfekt dafür geeignet wäre. Bringt unser Jungtier dorthin und beobachtet, wie es sich schlägt.", sourceObjective = "Besiegt das Jungtier der Vil'thik in einem Haustierkampf mit Eurem Schattendornjungtier in Eurer Gruppe.", completion = "Unser Kleiner hat offensichtlich einiges im Kampf gegen den Mantis gelernt.\n\nEr kann es sicher bald mit ausgewachsenen Gegnern aufnehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58862] = { id = 58862, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der kleinste Verteidiger", description = "Die Mogu der Baruk sind bekannt dafür, uralte Statuen zu beleben und sie als Verteidiger ihres Territoriums zu nutzen. Diese Statuen sind zähe Gegner, und von einem Kampf gegen einen solch widerstandsfähigen Gegner kann man sicher viel lernen.\n\nGlücklicherweise scheint einer ihrer Steinformer versehentlich eine kleine Statue zum Leben erweckt zu haben. Sie wurde von ihrem Moguschöpfer für nutzlos befunden, könnte sich für unser Jungtier jedoch als wertvolle Trainingsgelegenheit erweisen.\n\nFindet diesen Miniaturverteidiger im Tal der Ewigen Blüten.", sourceObjective = "Besiegt den steinernen Verteidiger der Baruk in einem Haustierkampf mit Eurem Schattendornjungtier in Eurer Gruppe.", completion = "Ich wusste, dass sich Euer kleines Jungtier gegen diese Mogukreatur durchsetzen würde!\n\nSeine Fähigkeiten nehmen von Tag zu Tag zu!", sourceObjectiveStatus = "unverified-source-field" }
quests[58863] = { id = 58863, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Individuelle Bestellung", description = "Ich glaube, ab jetzt können wir mit Stolz sagen, dass unser kleiner Schützling kein Jungtier mehr ist, sondern ein voll ausgewachsener Aqir. Er ist so groß geworden, dass er Euch sogar in die Schlacht tragen könnte.\n\nMoment mal, das ist ein großartige Idee!\n\nIhr solltet mit Schmied Abasi über die Herstellung eines Sattels sprechen.", sourceObjective = "Sprecht mit Schmied Abasi in Ramkahen.", completion = "Ich bin sicher, dass ich für diese Kreatur einen passenden Sattel herstellen kann.\n\nIch brauche allerdings zuvor Eure Hilfe bei einigen Sachen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58865] = { id = 58865, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fremdartige Waffen", description = "Für die Herstellung des Sattels für Euer Reittier brauche ich bestimmte Materialien. Ich brauche hauptsächlich Metalle, die leichter sind als das, was ich hier zur Verfügung habe.\n\nIch habe beobachtet, dass die Kultisten des Schwarzen Imperiums Waffen bei sich tragen, die aus fremdartigen, unfassbar leichten und stabilen Materialien hergestellt wurden.\n\nWenn Ihr mir einige dieser Waffen bringen könntet, könnte ich dieses Metall vielleicht einschmelzen und in einen Aqirsattel umschmieden.", sourceObjective = "Sammelt 12 Waffen des Schwarzen Imperiums von Kultisten des Schwarzen Imperiums in Uldum und dem Tal der Ewigen Blüten.", progress = "Habt Ihr meine Materialien gefunden?", completion = "Diese Waffen... sind gleichermaßen verstörend wie faszinierend.\n\nIch werde sie sofort einschmelzen. Besucht mich morgen und holt Euren Sattel ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[58866] = { id = 58866, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht ohne meine Drohne", description = "Der Sattel ist fertig. Die Arbeit mit diesem verderbten Metall war wirklich keine Freude, aber ich kann jetzt mit Sicherheit sagen, dass das bei Weitem der beste Sattel ist, den ich jemals gefertigt habe.\n\nIch weiß, er sieht... brutal aus, aber ich versichere Euch, dass Euer Aqir ihn recht bequem finden wird.\n\nIch hoffe, er leistet Euch gute Dienste.", sourceObjective = "Bringt den andersweltlichen Sattel zu H'partho Ardoros in Ramkahen.", progress = "Konnte der Schmied Euch helfen?", completion = "Ich bin beeindruckt. Ich hätte nicht gedacht, das Abasi so etwas überhaupt herstellen kann.\n\nUnser kleiner Freund ist jetzt wohl bereit, das Nest zu verlassen. Kümmert Euch gut um ihn!\n\nUnd besucht mich immer mal wieder.", sourceObjectiveStatus = "unverified-source-field" }
quests[58869] = { id = 58869, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlacht um das Winterschlafbecken", description = "Hier stellen wir uns dem Gefecht. Die Drust und ihre Schergen haben uns fast überrannt.\n\nAber wir lassen nicht zu, dass sie das Winterschlafbecken zerstören. Und auch nicht, dass sie unsere Anima oder unsere Wildsamen stehlen.\n\nKämpft mit uns. Vertreiben wir sie gemeinsam.", sourceObjective = "Gewinnt die Schlacht um das Winterschlafbecken.", completion = "Heute waren wir siegreich.\n\n...Aber ich befürchte, wir könnten Ysera verloren haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[58871] = { id = 58871, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entzweite Geweihe", description = "Der Fluch, der auf Qadarin liegt, ist mächtig.\n\nAber ich werde ihn brechen.\n\n<Thiernax schnaubt.>\n\nDer Tod konnte uns nicht voneinander trennen. Ich werde mich auch jetzt nicht von ihm losreißen lassen.\n\n<Thiernax mustert Euch und Shandris mit ernstem Blick.>\n\nGewährt mir Eure Hilfe, und ich werde Euch im Gegenzug mit der Nachtkriegerin Eurer Welt helfen. Ich verspreche nicht, dass ich sie retten kann... aber ich werde mein gesamtes Wissen mit Euch teilen.\n\nKehrt zum Herz des Waldes zurück und berichtet Lord Herne, was geschehen ist. Wir werden uns dort treffen.", sourceObjective = "Meldet Euch bei Lord Herne im Herz des Waldes. Sprecht danach mit Mondbeere.", progress = "Das ist sogar noch schlimmer, als ich erwartet hatte.", completion = "Ich wette, diese Spriggans dachten, dass dies ein großer Spaß wird. Aber wir werden zuletzt lachen!", sourceObjectiveStatus = "unverified-source-field" }
quests[58876] = { id = 58876, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verlorener Schwarm", description = "<Ein kleiner Drache taucht aus einer Seitenkammer innerhalb von N'Zoths großem Panzer auf. Er wirkt verwirrt.\n\nIhr vermutet, dass diese Kammern dazu benutzt wurden, um die Drachen zu verderben, indem sie direkt N'Zoths dunklem Geflüster ausgesetzt wurden. In ihrer Jugend hätte sie das in den Wahnsinn getrieben, mehr noch als alle anderen Mitglieder des Zwielichtdrachenschwarms, denen Ihr bisher begegnet seid.\n\nDieser Wahnsinn wäre nicht mehr rückgängig zu machen.\n\nAber vielleicht ist es für diesen hier noch nicht zu spät...>", sourceObjective = "Bringt die Brut von Vexiona zu Furorion in die Herzkammer.\n\nBereitgestellter Gegenstand:", completion = "Ich spüre großen Schmerz, Verwirrung und Verlustgefühle in diesem Jungtier. Diese arme Kreatur hat ein kurzes, herzzerreißendes Leben geführt.\n\nWie viele meiner Art hatte sie unter... anderen zu leiden.\n\n<Furorion wirkt einen Moment lang gequält.>\n\nEines Tages, Kleiner, werden wir uns wiederfinden.\n\n<Furorion berührt den Kopf des Drachen und schließt seine Augen.>\n\nSo, dein Geist ist befreit.\n\nEr ist noch jung. Er hat noch viel zu lernen und mehr zu erleben. Ich kann doch darauf vertrauen, dass Ihr Euch um ihn kümmern werdet?\n\nEnttäuscht mich nicht, Held.", sourceObjectiveStatus = "unverified-source-field" }
quests[58877] = { id = 58877, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht des Todes wächst", description = "Hört gut zu, {name}. Eine Zeit gewaltiger Zerstörung zieht am Horizont herauf, die unsere Existenz selbst infrage stellen wird. Mehr denn je müssen wir uns jetzt zur Verteidigung Azeroths erheben.\n\nAus diesem Grund darf auch Euer Volk ab jetzt in den Reihen meiner Champions dienen. Euer Opfer unterscheidet Euch von all den anderen. Erhebt Euer Haupt. Ihr werdet für alle Zeiten ein Todesritter der Schwarzen Klinge sein.\n\nUnd jetzt legt Euren Treueschwur ab.", sourceObjective = "Schwört dem Lichkönig die Treue.", progress = "Schwört Eure Treue, {name}.", completion = "Ich nehme Euren Schwur an. Leistet uns gute Dienste.\n\nZu diesem Zweck wurden neue Waffen geschmiedet, die eines Ritters der Schwarzen Klinge würdig sind.\n\nTrefft Eure Wahl, mein Champion.", sourceObjectiveStatus = "unverified-source-field" }
quests[58879] = { id = 58879, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rackern fürs Alpaka", progress = "<Es schnuppert neugierig in Richtung Eures Rucksacks und beäugt diesen eindringlich.>", completion = "<Es mampft begeistert die Gersahlblätter und summt zufrieden.>" }
quests[58881] = { id = 58881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[58887] = { id = 58887, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir alpaken's dann mal", sourceObjective = "<Das freundliche Alpaka sieht Euch mit offenem Blick an und ist offensichtlich dankbar, dass Ihr ihm immer wieder sein Lieblingsfutter bringt. Es macht den Eindruck, dass es sich Euren Abenteuern in der Wüste gern anschließen würde.>", sourceObjectiveStatus = "unverified-source-field" }
quests[58900] = { id = 58900, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine sichere Wette", sourceObjective = "Trefft Euch mit Anzio am Eingang zum Theater der Schmerzen.", completion = "Hierfür seid Ihr weit gereist.", sourceObjectiveStatus = "unverified-source-field" }
quests[58902] = { id = 58902, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidiger von Azeroth", description = "Eine ausgezeichnete Wahl.\n\nUnruhige Zeiten stehen bevor. Als <einer/eine> der wenigen Auserwählten ist es Eure Bürde und Euer Privileg, unsere Welt zu verteidigen. Das ist eine große Ehre.\n\nAber Ihr solltet auch wissen, dass Euch der Zorn der Unwissenden treffen wird. Oftmals sind Sterbliche unfähig, hinter unser angsteinflößendes Äußeres zu blicken. Beachtet diese Narren nicht und tut, was getan werden muss.\n\nSprecht mit Eurem Kommandanten. Benutzt danach dieses Schwarze Tor, um zum Land der Lebenden zu reisen und Euer Schicksal zu wählen.Ihr erlernt:", sourceObjective = "Sprecht mit Hochlord Darion Mograine. Benutzt danach das Schwarze Tor des Hochlords, um nach Sturmwind zu reisen. Trefft Euch nach Eurer Ankunft dort mit Chromie.", sourceObjectiveStatus = "unverified-source-field" }
quests[58903] = { id = 58903, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidiger von Azeroth", description = "Eine ausgezeichnete Wahl.\n\nUnruhige Zeiten stehen bevor. Als <einer/eine> der wenigen Auserwählten ist es Eure Bürde und Euer Privileg, unsere Welt zu verteidigen. Das ist eine große Ehre.\n\nAber Ihr solltet auch wissen, dass Euch der Zorn der Unwissenden treffen wird. Oftmals sind Sterbliche unfähig, hinter unser angsteinflößendes Äußeres zu blicken. Beachtet diese Narren nicht und tut, was getan werden muss.\n\nSprecht mit Eurem Kommandanten. Benutzt danach dieses Schwarze Tor, um zum Land der Lebenden zu reisen und Euer Schicksal zu wählen.Ihr erlernt:", sourceObjective = "Sprecht mit Hochlord Darion Mograine. Benutzt danach das Schwarze Tor des Hochlords, um nach Orgrimmar zu reisen. Trefft Euch nach Eurer Ankunft dort mit Chromie.", sourceObjectiveStatus = "unverified-source-field" }
quests[58904] = { id = 58904, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Splitter der Verderbnis", description = "<Ihr bemerkt, wie etwas Dunkles und Unmenschliches an Eurem Verstand zieht. Tastende Tentakel tauchen in Euren Geist ein und zerren an ihm. Ihr fühlt den Zwang, noch mehr Splitter zu sammeln... und zwar alle.>", sourceObjective = "Sammelt 20 Splitter der Verderbnis.", progress = "<Der Götze zerrt an Eurem Innersten und will, dass Ihr ihn berührt.>", completion = "<Ihr spürt eine unheilvolle Präsenz in Eurem Geist. Sie scheint... sehr zufrieden zu sein.>", sourceObjectiveStatus = "unverified-source-field" }
quests[58905] = { id = 58905, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pelagos einsammeln", description = "Pelagos müsste die Samen jetzt haben! Ohne Samen kann ich das Ritual nicht einleiten. Er ist wahrscheinlich immer noch beim Klauenkamm.\n\nWir sehen Euch dort!", sourceObjective = "Trefft Euch mit Pelagos, Weidenblüte und Larvi beim Klauenkamm.", completion = "Hoppla. Falsche Samen. Ich hoffe, wir finden noch Verwendung für sie.", sourceObjectiveStatus = "unverified-source-field" }
quests[58908] = { id = 58908, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orientierung", description = "Sturmwind hat Abenteurern wie uns viel zu bieten, ist aber viel zu groß, um alles zu Fuß zu erkunden. Die Kapitänin hat dafür gesorgt, dass Ihr ein Reittier erhaltet, um besser herumzukommen.\n\nSie hat gesagt, Ihr sollt mit Locke bei den Ställen in der Altstadt sprechen... aber mir fällt der Weg dorthin gerade nicht ein.\n\nKeine Sorge, {name}! Wir müssen nur eine Wache nach der Wegbeschreibung fragen. Wenn Ihr den Weg nicht kennt, könnt Ihr die Stadtwachen nach dem Weg fragen.\n\nErkundigen wir uns doch bei einer Wache in der Nähe, wie wir zum Stallmeister in der Altstadt kommen!", sourceObjective = "Sprecht mit Locke bei den Ställen in der Altstadt.", progress = "Willkommen bei den Ställen, {class}. Ich habe Euch erwartet.", completion = "Ihr seid also der Neuankömmling, von dem ich so viel gehört hab?\n\nIch heiße Locke. Ist mir ein Vergnügen, Euch kennenzulernen, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[58909] = { id = 58909, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lizenz zum Reiten", description = "Die Kapitänin hat schon gesagt, Ihr wolltet Euch hier heute ein Reittier holen. Ich hoffe, Ihr habt Euch unterwegs nicht verlaufen!\n\nAber bevor Ihr jetzt in den Sonnenuntergang reitet, müsst Ihr erst mal lernen, wie man... reitet. Zum Glück haben wir hier eine Reitlehrerin!\n\nSprecht mit Darlene Stokx, wenn Ihr lernen wollt, wie man reitet.", sourceObjective = "Sprecht mit Darlene Stokx, um die Fähigkeit 'Unerfahrenes Reiten' zu erlernen.", completion = "Nachdem Ihr jetzt die Grundlagen erlernt habt, kommt einfach jederzeit wieder, wenn Ihr Eure Reitkünste verbessern oder ein weiteres Reittier kaufen wollt!", sourceObjectiveStatus = "unverified-source-field" }
quests[58910] = { id = 58910, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was ist Eure Spezialität?", description = "Hey, {name}! Habt Ihr Euch schon für eine Kampfspezialisierung entschieden?\n\nAls {class} kennt Ihr ja schon die verschiedenen Klassen für Abenteurer. Aber habt Ihr gewusst, dass es bei jeder Klasse auch noch verschiedene Spezialisierungen gibt?\n\nWelche Spezialisierung man wählt, ist eine wichtige Entscheidung. Eure Spezialisierung bestimmt, welcher Platz Euch im Kampf in Eurer Gruppe zufällt und auch, welche Waffen und Fähigkeiten Ihr einsetzt.\n\nMithlos Falkenbusch über die Spezialisierungen!", sourceObjective = "Sprecht mit Mithlos Falkenbusch, um mehr über Kampfspezialisierungen zu erfahren.", completion = "Eine ausgezeichnete Wahl für Eure Spezialisierung, {name}.\n\nIhr dürft Eure neuen Fähigkeiten gern mal draußen an den Trainingsattrappen ausprobieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[58911] = { id = 58911, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zuhause ist, wo man seine Ruhe hat", description = "Ich weiß ja nicht, wie es Euch geht, aber von all dieser Rennerei krieg ich immer furchtbaren Durst!\n\nWarum gehen wir nicht mal zum \"Pfeifenden Schwein\", legen die Füße hoch und trinken einen Krug kühlen Mondbeerensaft?\n\nUnd wenn wir schon da sind, sprecht mal mit der Gastwirtin Maegan, um das Pfeifende Schwein zu Eurem neuen Zuhause zu machen. Solltet Ihr in Zukunft mal ohne Flugmeister dastehen, könnt Ihr dann mit Eurem Ruhestein direkt ins Gasthaus zurück.\n\nDas ist nicht nur schneller als ein Greif, sondern spart Euch auch ein paar Kupfermünzen!", sourceObjective = "Sprecht mit Maegan Tillman, um die Taverne \"Zum Pfeifenden Schwein\" als Euren Heimatort festzulegen.", progress = "Wie kann ich Euch heute helfen, {class}? Sucht Ihr nach einer Bleibe?", completion = "Solange die Taverne \"Zum Pfeifenden Schwein\" Euer Heimatort ist, sorgen wir dafür, dass ihr Feuer in Eurer Abwesenheit niemals verlischt.", sourceObjectiveStatus = "unverified-source-field" }
quests[58912] = { id = 58912, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein wichtiges Treffen", description = "Ich habe in ganz Sturmwind nach Euch gesucht, {name}.\n\nDie Kapitänin hat dem König ihren Bericht vorgelegt. Anscheinend benötigt Sturmwind erneut Eure Dienste.\n\nDie Anführer der Allianz haben sich zu einem Treffen in Burg Sturmwind versammelt, und König Wrynn höchstpersönlich besteht auf Eure Anwesenheit. Ich sollte Euch unverzüglich finden und diese Nachricht überbringen.\n\nEs war mir eine Ehre, mit Euch zu dienen, {name}. Möge das Licht Euch auf all Euren Wegen segnen.", sourceObjective = "Sprecht mit Kapitänin Garrick in Burg Sturmwind.", completion = "Gut, dass Ihr da seid. König Wrynn und die anderen erwarten Euch schon.", sourceObjectiveStatus = "unverified-source-field" }
quests[58914] = { id = 58914, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ende eines Kriegers", description = "Hey, {name}! Ihr seid <ein/eine:c> {class}, richtig? Vielleicht könnt Ihr ja diese... Situation aufklären.\n\nIch habe mich mit Lindies Gerät hier in der Gegend umgesehen und einen Geist getroffen, der \"wahren\" Kriegern Macht verspricht.\n\nIch weiß ja, dass Ihr noch nicht allzu lang dabei seid, aber warum schaut Ihr nicht mal da vorbei?\n\nGegen diese Oger können wir jeden Vorteil gut gebrauchen.", sourceObjective = "Sprecht mit dem seltsamen Geist an der Finsterbrecherbrücke.", completion = "Ihr seid nicht der Held aus Mythen und Legenden... Aber Ihr habt Potenzial.\n\nSteht still und ich teile meine mächtigste Technik mit Euch.\n\nUnd dann bitte ich Euch, mich endlich von diesem Leid zu erlösen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58915] = { id = 58915, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hjalmars endgültige Hinrichtung", description = "Jetzt beherrscht Ihr meine stärkste Fertigkeit, <junger Krieger/junge Kriegerin>.\n\nVersetzt mir nun damit den endgültigen Todesstoß! Seit einer halben Ewigkeit halten diese Oger meinen Geist hier gefangen, weil ich es gewagt habe, mich gegen sie zu stellen.\n\nNur ein glorreicher Tod kann mir die ewige Ruhe schenken.\n\nUnd nur dann werde ich im nächsten Leben meine Brüder und Schwestern wiedersehen.", sourceObjective = "Tötet Hjalmar den Unvergänglichen. Um ihn wirklich zu töten, müsst Ihr 'Hinrichten' einsetzen.", completion = "Klingt so, als hättet Ihr ein ganz schönes Abenteuer hinter Euch! Was glaubt Ihr? Wohin ist dieser Geist verschwunden, nachdem Ihr mit ihm gekämpft habt?", sourceObjectiveStatus = "unverified-source-field" }
quests[58916] = { id = 58916, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schreckensvorbereitung", description = "Graf Denathrius hat angeordnet, dass ich Euch bei den Jagdvorbereitungen helfe. Jeder Jäger muss hier im Hain des Schreckens dabei helfen, eine Seele vorzubereiten.\n\nIch habe hier eine störrische Seele, die sich sehr unkooperativ zeigt: Hundemeister Loksey. Jetzt ist er an der Reihe, gejagt zu werden.\n\n<Die Furchthetzerin gibt Euch einen Satz hoffnungsbrechende Seelenketten.>\n\nDemoralisiert diese Seele. Sie darf diesen Ort mit keinem Funken Hoffnung verlassen. Die Jagd soll die Seelen brechen, damit sie den Prozessen von Revendreth gegenüber weniger... widerspenstig ist.", sourceObjective = "Bereitet Hundemeister Loksey auf die Büßerjagd im Hain des Schreckens vor.", completion = "Die Seele ist fast bereit.\n\nWir haben die Gelegenheit, sie fertig vorzubereiten und uns dabei gleichzeitig um ein Problem zu kümmern.", sourceObjectiveStatus = "unverified-source-field" }
quests[58917] = { id = 58917, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ende eines Schurken", description = "Coulston Nereus, ein Schurke der verschollenen Expedition, wollte die Insel nach der Landung nach möglichen Gefahren absuchen.\n\nAls Henry ihn zum letzten Mal gesehen hat, war er unterwegs in Richtung Norden, zu einer Höhle in der Nähe.\n\nKönntet Ihr Kontakt zu Coulston aufnehmen? Vielleicht kann er uns bei der Rettungsmission helfen.\n\nOh, und seid vorsichtig, wenn Ihr nach Norden geht. Alaria hat in der Gegend einen ziemlich aggressiven Bären gesehen.", sourceObjective = "Schleicht Euch mit 'Verstohlenheit' unbemerkt durch das Gelände und sucht den Schurken der ersten Expedition.", progress = "Habt Ihr die Wurzeln? Stellt sicher, dass dieser Bär weit weg ist, wenn Ihr sie erntet.", completion = "Hier ist das Geheimnis, wie man diese Gifte herstellt. Hat mich eine Ewigkeit gekostet, das herauszufinden.\n\nAber da ich Euch jetzt gelehrt habe, wie es geht, könnt Ihr jederzeit mehr davon herstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58918] = { id = 58918, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Huwerath" }
quests[58923] = { id = 58923, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Dienst eines Paladins", description = "Mir ist bei der Verwendung von Lindies Späh-o-Matik etwas Seltsames passiert, worüber Ihr wahrscheinlich Bescheid wissen solltet.\n\nAuf einem Hügel in der Nähe ist der Geist eines Paladins erschienen. Sie hat direkt in die Späh-o-Matik geblickt und nach Euch gefragt.\n\nIch verstehe nicht viel vom Licht und Paladinen, aber ich denke, Ihr solltet sie nicht ignorieren.", sourceObjective = "Sprecht mit dem Geist des Paladins.", progress = "Seid gegrüßt, {name}. Schön, Euch endlich von Angesicht zu Angesicht zu sehen..", completion = "Wer dem Licht dient, weiß um seinen Segen. Nehmt nun dieses Geschenk, {class}.\n\nNutzt es, wenn Eure Kräfte schwinden, wenn alle Hoffnung verloren scheint. Das Licht wird Euch vor dem Übel beschützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58931] = { id = 58931, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sündenstein von Inquisitorin Stelia", description = "Man entkommt seiner Vergangenheit nie, <Schlundgänger/Schlundgängerin>.\n\nJeder Venthyr kam einst als Seele nach Revendreth und war mit den Sünden des sterblichen Lebens belastet.\n\nWie alle Seelen meißelten sie ihre wahren Namen und schändlichsten Vergehen in Sündensteine.\n\nDerart private Kenntnisse können eine mächtige Waffe sein, wenn sie schlau eingesetzt werden.\n\nFindet die Sündensteine der Inquisitoren, die der Anklägerin helfen, damit Ihr sie töten könnt. Beginnt mit Stelia.\n\nWenn sie dann alle tot sind, bringt mir den Sündenstein der Anklägerin. Ich kümmere mich selbst um sie.", sourceObjective = "Sammelt Gruftschlüssel der Eingeschworenen und öffnet Gruften, bis ihr den Sündenstein von Inquisitorin Stelia findet.", progress = "Inquisitoren verstecken ihre Sündensteine, um sich selbst zu schützen.", completion = "Gut. Temel wird wissen, wie man den Sündenstein einsetzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[58932] = { id = 58932, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Temel, der Sündenherold", description = "<Bevor er abfliegt, ruft Echelon eine weitere Anweisung.>\n\nEnteignet auch Temel. Er weiß, wie man den Sündenstein richtig nutzt.", sourceObjective = "Besiegt Grufthüter Kassir, um Temels Gehorsam zu verdienen.", completion = "<Echelon beäugt Temel misstrauisch.>\n\nIch mochte diesen Zwerg noch nie.", sourceObjectiveStatus = "unverified-source-field" }
quests[58933] = { id = 58933, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Tödlichste aller Gifte", description = "Ihr habt das Gift. Dann läuft die Zeit des Ogers jetzt ab. Gutgruk der Zähe.\n\nNormalerweise patrouilliert er um ihre Zitadelle. Wahrscheinlich sucht er genau in diesem Augenblick nach Eurer Expedition!\n\nVergiftet Eure Klingen und erledigt dieses Monster.", sourceObjective = "Tötet Gutgruk den Zähen.", completion = "Wir sorgen dafür, dass niemand das Opfer vergisst, das Coulston Nereus gebracht hat.\n\nGut, dass dieses Gift den Oger aufgehalten hat. Ohne wäre es bestimmt eng geworden!", sourceObjectiveStatus = "unverified-source-field" }
quests[58936] = { id = 58936, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wildtierkontrolle", description = "Der Animamangel, den die Dürre hervorgerufen hat, hat die Fleddermäuse im Hain des Schreckens aggressiv gemacht.\n\nDies ist ein förmliches Ersuchen um eine Ausdünnung des Bestandes. Wir müssen die Kontrolle über unsere Schöpfung zurückerlangen.\n\n-Herdenhüter Sergio", sourceObjective = "Tötet 6 Fleddermäuse im Hain des Schreckens.", completion = "Das Gleichgewicht kehrt zurück. Bitte nehmt diese Bezahlung von mir und den anderen hiesigen Hütern an.", sourceObjectiveStatus = "unverified-source-field" }
quests[58937] = { id = 58937, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Miese Milben", description = "Oh nein! Es wimmelt da nur so vor Milben!\n\nSie sind zwar so niedlich wie Larvi, aber sie wachsen zu grauenvollen Gorm heran! Wenn wir ein paar von ihnen beseitigen können, müssen die Sylvari später weniger von ihnen bekämpfen.\n\nSie können sich eingraben, also ist es am besten, sie mit Pelagos' roten Samen abzufackeln. Die sind vielleicht doch noch zu etwas gut.", sourceObjective = "Verbrennt 20 mutierende Milben mit Pelagos' Flammenpeitschensamen.", completion = "So einfach kommen sie nicht mehr zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[58938] = { id = 58938, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gorm, geh weg!", description = "Diese roten Samen werden uns noch nützlich sein. Sie stammen von einer sehr gefährlichen Pflanze und sind recht instabil. Um den blauen Samen zu sichern, den wir wirklich haben wollen, könnten die hier von Nutzen sein.\n\nLasst uns ein paar dieser Gorm beseitigen und nach dem richtigen Samen suchen.", sourceObjective = "Tötet 10 ausgewachsene Gorm.", progress = "Wir müssen uns einen Weg bahnen.", completion = "Diese Samen sind nicht nur nützlich, sie sind gefährlich!", sourceObjectiveStatus = "unverified-source-field" }
quests[58939] = { id = 58939, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der blaue Samen", description = "Ich erinnere mich an einen blauen Samen mit roten Blättern in der Nähe, aber er war in einer Höhle hinter einer Wand aus Dornenranken. Ist mir vorher nicht eingefallen, aber vielleicht könntet Ihr die roten Samen verwenden, damit wir hineingelangen?\n\nIch wünschte, ich hätte die Anweisungen nicht durcheinandergebracht, dann wären wir nicht in dieser Lage. Aber vielleicht wendet sich ja alles noch zum Guten. Gehen wir!", sourceObjective = "Findet den Höhleneingang, überwindet die Sperre aus Dornenranken und beschafft den gereiften Animasamen.", progress = "Das war doch ein ziemlich spaßiges Abenteuer. Findet Ihr nicht auch?", completion = "Der Samen!", sourceObjectiveStatus = "unverified-source-field" }
quests[58941] = { id = 58941, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alphafledermaus", description = "Fleddermäuse sind für uns recht nützlich. Wir erschaffen sie auf dieselbe Weise wie die Steingeborenen, aber ihnen mangelt es an deren... Intelligenz. Mit nur sehr wenig Anleitung lehren sie auch die störrischsten Seelen das Fürchten.\n\nDurch die Animadürre hat unsere Kontrolle über sie abgenommen. Den größten Schaden hat eine von ihnen namens Dämmerschrecken angerichtet.\n\nDadurch bietet sich uns eine Chance. Nehmt diese Seele und lockt sie an. Wenn sie geschwächt ist, können wir sie einfangen und für unsere Zwecke nutzen.", sourceObjective = "Bindet Hundemeister Loksey an den Pfahl im Hain des Schreckens. Schwächt dann Dämmerschrecken, um sie einzufangen.", progress = "Habt Ihr Dämmerschrecken gefangen?", completion = "Jetzt, da Dämmerschrecken gefangen ist, haben wir etwas mehr Kontrolle über dieses Gebiet.", sourceObjectiveStatus = "unverified-source-field" }
quests[58946] = { id = 58946, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schild des Göttlichen", description = "Die Insel wurde durch nekrotische Magie verflucht. Das Licht erreicht diesen Ort kaum noch.\n\nNutzt 'Gottesschild', um die Barriere dort unversehrt zu durchqueren und zerstört diesen abscheulichen nekrotischen Altar.\n\nZeigt der Finsternis auf dieser Insel, dass Ihr im Schutze des Lichtes wandelt.", sourceObjective = "Durchquert die nekrotische Barriere mit 'Gottesschild' und zerstört den nekrotischen Altar. Wenn Ihr die Abklingzeit von 'Gottesschild' verringern müsst, sprecht mit Yorah.", completion = "Das habt Ihr gut gemacht, {name}. Vernichtet diese furchtbare Magie, wo immer Ihr sie vorfindet.\n\nMeine Aufgabe ist erfüllt. Das Licht ruft meinen Namen.\n\nViel Glück und vergesst nie: Wo Ihr auch hingeht, die Wärme des Lichts wird Euch immer beschützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58947] = { id = 58947, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eignungsprobe", description = "Viele der größten Legenden von Maldraxxus haben sich kämpfend ihren Ruhm im Theater der Schmerzen verdient.\n\nWenn Ihr in ihre Fußstapfen treten wollt, müsst Ihr beweisen, dass Ihr das Zeug dazu habt, da drin zu überleben.\n\nBesiegt Bewerter Malus und Testerin Sahaari im Kampf. Zeigt, zu was Ihr imstande seid!", sourceObjective = "Bewerter Malus und Testerin Sahaari besiegt.", completion = "Ihr habt Euch als würdig erwiesen! Ich werde dafür sorgen, dass Ihr bald einen Kampf bestreiten könnt!", sourceObjectiveStatus = "unverified-source-field" }
quests[58948] = { id = 58948, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mahlzeit!", description = "Ich koche Eintopf zum Abendessen, aber unser Hasenfleisch ist alle.\n\nKannst du noch einmal losziehen und mir etwas Fleisch besorgen?\n\nOh, sei bitte vorsichtig. Ich habe vorhin irgendetwas heulen gehört. Eigentlich kommen die Wölfe nur nachts heraus.", sourceObjective = "Besorgt 4 Stücke Hasenfleisch.", progress = "Sch, sch, Gwendolyn. Ist ja gut, meine Kleine.", completion = "Das dürfte reichen. Danke, Liebster.", sourceObjectiveStatus = "unverified-source-field" }
quests[58949] = { id = 58949, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Millis Garten", description = "Alma war vorhin hier und hat Milli ein paar Blumensamen mitgebracht, die sie im Garten einpflanzen will.\n\nEs freut mich wirklich, dass sich unsere Tochter so für den Garten begeistert, aber ich habe keine Zeit, dauernd ihr Kleid zu waschen, wenn sie mal wieder von oben bis unten voll Schlamm ist!\n\nWürdest du das Graben übernehmen, damit sie sich nicht zu schmutzig macht?", sourceObjective = "Benutzt Eure Schaufel, um 3 Stücke ungepflügtes Erdreich zu pflügen.", completion = "Du bist der beste Papa auf der Welt!\n\n<Milli umarmt ganz fest Eure Knie.>\n\nHier, ich hab Limonade für dich gemacht. Aber ich hab nur genug für ein Glas. Also trink nicht zu schnell!", sourceObjectiveStatus = "unverified-source-field" }
quests[58950] = { id = 58950, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holz für Seenhain", description = "Magistrat Solomon hat um ein Bündel Holz für seinen Herd gebeten. Aber er ist wohl zu beschäftigt, um es selbst abzuholen.\n\nBring es ihm doch bitte im Rathaus vorbei. Er wäre dir sicher dankbar.", sourceObjective = "Bringt das Holzbündel zu Magistrat Solomon ins Rathaus von Seenhain.", progress = "Die Leute sind angespannt, Ben. Es ist meine Aufgabe, sie zu beruhigen.", completion = "Danke, dass Ihr das Holz gebracht habt. Ich wollte es selbst holen, aber die Leute haben den ganzen Tag Zeter und Mordio geschrien.", sourceObjectiveStatus = "unverified-source-field" }
quests[58951] = { id = 58951, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das letzte Gefecht von Seenhain", description = "Es bleibt keine Zeit zum Evakuieren... nicht, wenn die Geißel hier ist!\n\nVerbarrikadiert die Fenster! Holt alle herein! Unsere einzige Hoffnung liegt darin, uns zu verstecken.", sourceObjective = "Stellt Euch gegen die Invasion der Geißel.", completion = "Diese arme Seele.\n\nEin ehrenwerter Mann... Dass er so grausam sterben musste...", sourceObjectiveStatus = "unverified-source-field" }
quests[58952] = { id = 58952, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Läuternde Flammen" }
quests[58953] = { id = 58953, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ende eines Priesters", description = "Ihr seid <ein ausgebildeter Priester/eine ausgebildete Priesterin>, nicht wahr, {name}? Dann ist das hier genau richtig für Euch.\n\nWir haben die Leichen der anderen Rekruten aus unserer Expedition gefunden.\n\nIch vermute, sie wurden an anderen Teilen der Insel angespült. Weit sind sie nicht gekommen.\n\nWenn Ihr einen Moment Zeit habt, würdet Ihr wohl ein paar Gebete für sie sprechen? Dann finden ihre Geister endlich Frieden.\n\nWir begraben die Leichen, sobald wir uns um die Oger gekümmert haben.", sourceObjective = "Findet die Leichen der Rekruten der ersten Expedition.", completion = "Wir haben keine Zeit für Geschwätz. Ich segne Euch direkt mit der Kraft der Auferstehung.\n\nEigentlich gibt's auch eine große Zeremonie dazu, aber wir haben ein dringendes Problem.\n\nWenn wir uns nicht beeilen, wird die Nekromantie der Oger bald die Seelen dieser armen Rekruten verschlingen!", sourceObjectiveStatus = "unverified-source-field" }
quests[58960] = { id = 58960, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Auferstehung der Rekruten", description = "Die Seelen der Rekruten sind nicht stark genug, der auf dieser Insel praktizierten dunklen Magie zu widerstehen.\n\nMit 'Auferstehung' könnt Ihr die Überreste der Rekruten vielleicht wieder ins Leben zurückrufen. Fleht das Licht an, ihnen noch eine Chance zu geben, solange ihre Seelen noch hier verweilen.\n\nSeit Jahren sitze ich schon auf dieser Insel fest und muss das Treiben dieser Oger hilflos mitansehen.\n\nJetzt wird abgerechnet.", sourceObjective = "Erweckt die Rekruten der Expedition wieder zum Leben.", completion = "Ihr habt alles, was es braucht, um ein sehr mächtiger {class} zu werden.\n\nUnd ich? Oh, mein Körper ist längst verrottet. Aber da jetzt endlich jemand diese Oger aufhält, kann ich in Frieden ruhen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58961] = { id = 58961, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überfallene Siedler" }
quests[58962] = { id = 58962, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Handel eines Hexenmeisters", description = "Während Ihr die Horden der Untoten niedergemäht habt, war ich mit Lindies Gerät unterwegs.\n\nIn der Nähe der Brücke habe ich wohl so etwas wie ein Portal gesehen und gleich daneben die Leiche eines Hexenmeisters, von dem wir dachten, er wäre bei dem Schiffbruch verschollen.\n\nKönnt Ihr Euch die Gegend mal genauer ansehen und das Portal schließen? Wir haben wirklich schon genug Probleme auf dieser Insel.", sourceObjective = "Untersucht die Leiche des Hexenmeisters der ersten Expedition.", progress = "Ich sehe, Ihr habt das Grimoire, das für das Bindungsritual verantwortlich ist.", completion = "Unsere Abmachung gilt.\n\nRuft mich aus der Leere, und ich eile herbei.\n\n<Der Leerwandler sieht zur Leiche des Worgen.>\n\nDann wollen wir mal sehen, ob Ihr stärker seid als die, die vor Euch kamen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58974] = { id = 58974, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überfallene Siedler" }
quests[58975] = { id = 58975, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schädlingsbekämpfung" }
quests[58976] = { id = 58976, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Erinnerung hinterher", description = "So etwas wie den Angriff auf den Tempel der Reinheit hat es in der Bastion noch nie gegeben. Zumindest nicht meines Wissens.\n\nWir müssen mehr erfahren. Das von dem Paragon erbeutete Fragment könnte die von uns gesuchten Antworten enthalten.\n\nIn der Nähe gibt es einen Ort, der Gedächtnisraum genannt wird. Dort können Aspiranten und Aufgestiegene gleichermaßen ihre Erinnerungen hervorrufen und aufbewahren. Wenn wir uns die Erinnerungen dieses Fragments ansehen können, erfahren wir vielleicht mehr über die sogenannten Verschmähten, und wenn wir ganz viel Glück haben, decken wir ihren Plan auf.\n\nWir treffen uns dort. Geht und dient.", sourceObjective = "Begebt Euch zum Gedächtnisraum.", completion = "<Mikanikos zeigt gereizt auf die Verschmähten hinter sich.>\n\nSeid Ihr hier, um zu helfen, DAS HIER in Ordnung zu bringen?", sourceObjectiveStatus = "unverified-source-field" }
quests[58977] = { id = 58977, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was ist in einer Erinnerung?", description = "Womöglich lassen sich Erinnerungen aus Fragmenten extrahieren, doch ich fürchte, sie könnten unbrauchbar sein. Dies ist kein ganzer Kyrianer, sondern nur ein winziger Teil! Ein seltsames, zerbrochenes Teil. Nicht einmal sprechen kann es!\n\nWenden wir den Extraktor an, dann werden wir sehen. Der Extraktor könnte explodieren. Oder auch nicht. Ist es das Risiko wert? Ich denke, ja.\n\nWas könnte es sonst geben? Vielleicht Erinnerungen. Vielleicht nichts. Oder etwas Anderes. Vielleicht müsst Ihr kämpfen! Bleibt wachsam, ja? Sammelt alles, was nach Verschmähten aussieht.\n\nSprecht, wenn Ihr bereit seid.", sourceObjective = "Sammelt Erinnerungen der Verschmähten aus dem Fragment von Lysonia.", progress = "Glaubt Ihr, dass wir die benötigten Informationen erhalten werden, {name}?", completion = "Wir haben es geschafft. Mit etwas Glück sind ihre Erinnerungen für uns erreichbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[58978] = { id = 58978, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lysonias Wahrheit", description = "Wenn ich es nicht mit eigenen Augen gesehen hätte, würde ich wahrscheinlich nicht glauben, dass so etwas möglich ist.\n\nIhr tragt jetzt ein bedeutendes Stück von Lysonia in Euch. Geht zu den Seelenspiegeln und öffnet Euch ihnen. Mit ein bisschen Glück werden sie auf ihre Essenz zurückgreifen, um eine Erinnerung der Verschmähten hervorzubringen.\n\nWenn das funktioniert, erfahren wir vielleicht in ein paar Minuten, was sie vorhaben!", sourceObjective = "Stellt Euch vor einen Seelenspiegel und erlebt Erinnerungen aus Lysonias Vergangenheit mit.", completion = "<Mikanikos zürnt im Stillen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[58979] = { id = 58979, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich habe Euch ERSCHAFFEN!", description = "Mir reicht es jetzt mit dieser Unverschämtheit.\n\nIch hätte da eine Idee, um die Persönlichkeit dieses Mnemis zurückzusetzen, aber dazu müsst Ihr ihn beschäftigen.\n\nEr wird versuchen, sich mit allen Mitteln gegen Euch zu wehren. Ich schlage vor, Ihr versucht, nicht zu sterben. Kleia kann sich gegen ihn behaupten, also versteckt Euch hinter ihr, wenn Euch danach ist.\n\nHopp, hopp!", sourceObjective = "Helft Mikanikos, Gedächtnishüter Mnemis zurückzusetzen.", completion = "Ich hoffe, Ihr verzeiht mir mein Verhalten. Ich war nicht ganz ich selbst.", sourceObjectiveStatus = "unverified-source-field" }
quests[58980] = { id = 58980, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mnemis, zu Euren Diensten.", description = "Seid gegrüßt, ich bin Gedächtnishüter Mnemis und ich würde mich sehr freuen, Euch behilflich zu sein.\n\nWenn ich mich recht entsinne, versucht Ihr, Zugang zu einer bestimmten Erinnerung zu erhalten. Aufgrund ihres Inhalts kann diese Erinnerung nur innerhalb der Kammer der Archon angesehen werden.\n\nUm Einlass in die Kammer zu bekommen, müsst Ihr Opfergaben für ihre beiden Wächter sammeln. Ich habe diese Opfergaben vor den Verschmähten verborgen, da diese keinen Zutritt dort haben.\n\nDer Oberste Schmied ist der Einzige unter Euch, der diese Befugnis erteilen kann. Wie praktisch!", sourceObjective = "Findet zwei Opfergaben im Gang der Erinnerungen und begebt Euch dann zur Kammer der Archon.", progress = "Habt Ihr die Opfergaben gefunden, von denen ich Euch erzählt habe?", completion = "Eure Suche war erfolgreich. Mit Freude sehe ich, dass Ihr unversehrt seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[58981] = { id = 58981, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verhärteter Bau" }
quests[58983] = { id = 58983, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle for Azeroth: Gezeiten des Krieges", description = "König Wrynn hat uns zu einem Kriegsrat einberufen. Es ist sehr dringend.\n\nAnscheinend gab es einigen Ärger mit der Horde, während wir unterwegs waren. Ihr habt den König mit Eurem Mut und Eurem Ehrgefühl bei unserer Mission auf der Insel des Verbannten sehr beeindruckt.\n\nDa Ihr jetzt endlich hier seid, wird der Rat unverzüglich beginnen.", sourceObjective = "Nehmt am Kriegsrat in Burg Sturmwind teil.", progress = "Danke für Euer Kommen.", completion = "Die Horde hat uns erneut zum Handeln gezwungen.\n\nDas können wir nicht tolerieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[58989] = { id = 58989, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einmaleins des Runenschmiedens", description = "Als Ritter der Schwarzen Klinge müssen wir immer auf verschiedenste Kampfsituationen vorbereitet sein. Zu diesem Zweck dürft Ihr die dunkle Kunst des Runenschmiedens ausüben. Damit können Runen von großer Macht in Eure Waffe graviert werden.\n\nÜber uns im Herzen von Acherus befinden sich Runenschmieden. Sucht eine davon auf und setzt Eure Macht ein, um eine Waffe mit einer Rune der Macht zu verstärken.", sourceObjective = "Benutzt die Fähigkeit 'Runen schmieden' aus Eurem Zauberbuch, um Eure Waffe mit einer Rune zu versehen.\n\nIhr könnt die Gravur jederzeit durch eine andere ersetzen, solange Ihr Euch in der Nähe einer Runenschmiede befindet.", progress = "Habt Ihr Eure Waffe mit einer Rune versehen, {name}?", completion = "Denkt daran, Runenschmieden findet man nur an einigen wenigen Orten. Dazu gehören Acherus und bestimmte Orte innerhalb von Eiskrone. Ihr dürft nur Eure eigenen Waffen in einer Runenschmiede gravieren.\n\nKehrt zurück, wenn Ihr die Rune ersetzen möchtet. Bis dahin, leidet wohl.", sourceObjectiveStatus = "unverified-source-field" }
quests[58990] = { id = 58990, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Titanusei" }
quests[58991] = { id = 58991, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdächtige Verderbnis", description = "<Dieser spezielle Gegenstand wirkt irgendwie ungewöhnlich. Vielleicht kann jemand in der Kammer etwas zu seinem Ursprung sagen.>", sourceObjective = "Sucht nach Antworten zu dem verderbten Gegenstand in der Herzkammer.", progress = "Habt Ihr etwas Interessantes gefunden?", completion = "Titanisches Läuterungssystem verfügbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[58992] = { id = 58992, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pastete geht immer", description = "Ich möchte etwas Warmes, Schmackhaftes und Klebriges backen!\n\nJawohl! Ich will eine herrliche Knochenmarkpastete machen! Wenn sie fertig ist, ist man garantiert pappsatt!\n\nNun, irgendein beliebiges Knochenmark reicht da nicht. Ich brauche das beste und seltenste Mark.\n\nUnd genau da kommt Ihr ins Spiel! Ihr müsst Mama helfen und das Knochenmark ausgraben. Ja... ausgraben.\n\nOh, und stellt Euch darauf ein, ein paar Köpfe einzuschlagen. Maldraxxus reagiert widerborstig, wenn es zerstückelt wird.", sourceObjective = "Sammelt 4 Maldraxxusknochenmark.", progress = "Gibt es eigentlich Pasteten, die nicht herrlich sind? Blutpastete, Knochenmarkpastete, Knochenmarkpudding...", completion = "Wenn das nicht die beste Marklieferung ist, die ich je gesehen habe!\n\nMama wird Euch heute ein Festmahl kochen!", sourceObjectiveStatus = "unverified-source-field" }
quests[58993] = { id = 58993, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwarmverteidigung" }
quests[58995] = { id = 58995, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich hab geträumt vor langer Zeit", description = "Was für eine Zeremonie. Wirklich alle sind gekommen. Dieses Ritual ist unerlässlich, um das Emblem des Aufstiegs wiederherzustellen und die Bastion zu erhalten.\n\nDie Winterkönigin und Weidenblüte haben uns gerettet. Hoffentlich können wir diese Schuld eines Tages begleichen.", sourceObjective = "Nehmt an der Zeremonie teil.", progress = "Habt Ihr das Gefäß?", completion = "Sie ist... Sie ist fort.", sourceObjectiveStatus = "unverified-source-field" }
quests[58996] = { id = 58996, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abels Schicksal", description = "<Schlundgänger/Schlundgängerin>, ich habe noch eine Aufgabe für Euch.\n\nVor einiger Zeit habe ich Seelenwächter Abel und andere entsandt, um ein paar Knochenbeißer, die Ärger machen, zu töten.\n\nSie sind noch nicht zurückgekehrt. Sucht sie, ja?", sourceObjective = "Untersucht das Schicksal von Seelenwächter Abel.", progress = "Was ist aus Abel geworden?", completion = "Sie wurden also besiegt? Und doch steht Ihr noch.\n\nSchande.", sourceObjectiveStatus = "unverified-source-field" }
quests[58997] = { id = 58997, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein bittersüßer Preis", description = "Ich... Ich weiß nicht, was ich sagen soll.\n\nJetzt bleibt nur noch eins zu tun. Weidenbl... das Gefäß... muss zurück zu Polemarch Adrestes in der Bastion gebracht werden. Dieses Opfer darf nicht umsonst gewesen sein.", sourceObjective = "Bringt das Gefäß des Ardenwalds zu Polemarch Adrestes in der Elysischen Feste in der Bastion zurück.", completion = "Ihr habt uns das Gefäß gebracht, das wir benötigen, um das Emblem des Aufstiegs zu vervollständigen. Und unter großen Opfern, wie ich gehört habe.\n\nWir müssen danach streben, unsere Freunde im Ardenwald eines Tages zu entschädigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[59000] = { id = 59000, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elemente der Verderbnis", description = "Verderbnis verhält sich oft rätselhaft. Sie breitet sich weit über Azeroth hinaus aus und berührt unsere intimsten Gedanken. Und manchmal verderbt sie verschiedene Relikte, wie Ihr mit eigenen Augen gesehen habt.\n\nObwohl ich nicht direkt etwas zu derartige Angelegenheiten sagen kann, bin ich sicher, dass MUTTER Informationen über diese sogenannten verderbten Gegenstände besitzt.", sourceObjective = "Sprecht mit MUTTER, um mehr über verderbte Gegenstände zu erfahren.", completion = "Titanisches Läuterungssystem aktiviert.", sourceObjectiveStatus = "unverified-source-field" }
quests[59002] = { id = 59002, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Pflicht eines Schamanen", description = "Seid gegrüßt. Eure Gefährten können mich nicht sehen. Nur Ihr könnt dies, denn Ihr wurdet in den schamanischen Künsten unterrichtet.\n\nDie Schattenenergie auf dieser Insel hält mein Rudel gefangen. Ich brauche Eure Hilfe, um es zu befreien.\n\nSammelt Schleierblüten, die hier in der Umgebung wachsen. Verbrennt sie gleich hier auf dem Lagerfeuer und atmet ihren Rauch ein.\n\nDann könnt Ihr meine Rudelgefährten sehen und sie von ihren Fesseln befreien.", sourceObjective = "Sammelt 4 Schleierblüten und verbrennt sie auf dem Lagerfeuer, um das Rudel des Geisterwolfes zu befreien.", progress = "Die Schleierblüten gewähren Euch die Weitsicht, die Ihr braucht, um mein Rudel zu retten.", completion = "Mein Rudel und ich sind zu schwach, um uns gegen die dunklen Mächte auf dieser Insel zu stemmen.\n\nAber mit dem letzten Rest unserer Kräfte können wir Euch unsere Macht gewähren.\n\nNutzt dies, um die Insel von der Nekromantie der Oger zu säubern.\n\nBefreit die unzähligen Seelen, die hier gefangen sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[59003] = { id = 59003, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entzündliche Kokons" }
quests[59004] = { id = 59004, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spritzschaden", description = "Die Truppen des Kerkermeisters verwenden animageladene Runen, um ihre Rüstungen zu verstärken, doch ohne diese Runen sind diese Truppen sehr viel schwächer!\n\nIch habe diese spezielle Formel entwickelt, um hartnäckige Flecken zu entfernen, aber damit müsste man auch magische Runen entfernen können!\n\nSpritzt meinen Zersetzungstrank auf die runenverstärkten Truppen. Je größer, desto besser! Sammelt dann die heruntergefallenen Runen ein, damit ich die Anima extrahieren kann.", sourceObjective = "Sammelt 50 animageladene Runen von runenverstärkten Truppen ein.", progress = "Habt Ihr aufräumen können?", completion = "Der Sieg wird unser sein, Schlundgänger!", sourceObjectiveStatus = "unverified-source-field" }
quests[59007] = { id = 59007, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seelenbrunnen" }
quests[59008] = { id = 59008, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprigganfesseln", description = "Ich bin so froh, dass Ihr und Qadarin des Weges gekommen seid! Diese Spriggans sind verrückt!\n\nHolt mich hier raus!\n\nIch wollte im Garten ein paar Kräuter sammeln, als sie mich geschnappt haben. Sie haben bestimmt auch andere Seelen gefangen!", sourceObjective = "Befreit Cirrik und rettet 8 Gefangene.", completion = "Das Einfangen von Seelen ist viel unverfrorener als ein typischer Streich der Spriggans. Ich frage mich, was sich geändert hat...", sourceObjectiveStatus = "unverified-source-field" }
quests[59009] = { id = 59009, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr rechtmäßiger Platz", description = "Mor'Bitan ist nicht mehr... und es war ein schmerzhaftes Ende.\n\nEure Standhaftigkeit trug einiges zu meinem Erfolg bei. Fürs Erste habt Ihr Euch meine Treue verdient. \n\nWollt Ihr dieses Reich wirklich beherrschen, so liegt noch viel vor Euch.\n\nSammeln wir uns beim Sitz neu.", sourceObjective = "Kehrt mit Eurer Runenklinge zum Sitz des Primus zurück.", progress = "Hattet Ihr Erfolg?", completion = "Es ist gut, Verbündete zu haben. Selbst wenn sie so dickköpfig sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[59011] = { id = 59011, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Tod liegt die wahre Probe", description = "Vyraz war es, der mich im Schlund gefangen gehalten hat. Er ist schon lange mit dem Haus der Rituale und dem Haus der Konstrukte im Bunde.\n\nUnd Euch wollte er zweifelsohne auch an diesen höllischen Ort verbannen.\n\nEs ist an der Zeit, dass er für seinen Verrat bestraft wird. Kommt mit mir und lasst ihn uns zusammen bekämpfen.", sourceObjective = "Stellt Vyraz wegen des Todes von Markgraf Krexus zur Rede.", completion = "Wir können die Stellung kaum halten. Schlagen wir schnell zu.", sourceObjectiveStatus = "unverified-source-field" }
quests[59014] = { id = 59014, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "König der Anhöhe", description = "Loksey ist bereit. Die Jagd kann endlich beginnen.\n\nBringt ihn zur Schwundgruft. Die Furchthetzerin und die anderen Jäger sind bereits dort.\n\nBeeilt Euch. Sie ist es nicht gewohnt, zu warten.", sourceObjective = "Bringt Hundemeister Loksey zur Furchthetzerin beim Schwundgrufthügel.", progress = "Wo ist die Seele?", completion = "Sollen wir beginnen?", sourceObjectiveStatus = "unverified-source-field" }
quests[59015] = { id = 59015, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feindselige Erinnerungen" }
quests[59016] = { id = 59016, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Uldum", description = "Unsere Ziele in Uldum werden durch das Auftauchen von Allianzabschaum blockiert.\n\nTötet so viele von ihnen, wie Ihr in der Region finden könnt, und meldet Euch wieder bei mir.", sourceObjective = "Tötet Mitglieder der Allianz in Uldum.", completion = "Gute Arbeit, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[59017] = { id = 59017, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Tal der Ewigen Blüten", description = "Unsere Ziele im Tal der Ewigen Blüten werden durch das Auftauchen von Allianzabschaum blockiert.\n\nTötet so viele von ihnen, wie Ihr in der Region finden könnt, und meldet Euch wieder bei mir.", sourceObjective = "Tötet Mitglieder der Allianz im Tal der Ewigen Blüten.", completion = "Gute Arbeit, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[59018] = { id = 59018, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Tal der Ewigen Blüten", description = "Unsere Mission im Tal der Ewigen Blüten wird durch die Übergriffe der Horde gestört.\n\nBegebt Euch ins Tal und schaltet so viele Mitglieder der Horde aus, wie Ihr nur könnt.", sourceObjective = "Tötet Mitglieder der Horde im Tal der Ewigen Blüten.", completion = "Gute Arbeit, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[59019] = { id = 59019, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Uldum", description = "Unsere Mission in Uldum wird durch die Übergriffe der Horde gestört.\n\nBegebt Euch nach Uldum und schaltet so viele Mitglieder der Horde aus, wie Ihr nur könnt.", sourceObjective = "Tötet Mitglieder der Horde in Uldum.", completion = "Gute Arbeit, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[59020] = { id = 59020, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der dritte Niedergang Kel'Thuzads", description = "Die Zeit ist gekommen, um Maldraxxus vom Verrat zu säubern.\n\nUnsere Armeen sind versammelt. Unsere Verbündeten stehen bereit. Die Kriegsmaschine ist in Bewegung.\n\nWir müssen diese Schlacht gewinnen, sonst sind die Schattenlande verloren.", sourceObjective = "Entfernt Kel'Thuzad aus Maldraxxus.", completion = "Kel'Thuzad fiel dem Verbannten in die Hände, doch zumindest geißelt seine Bosheit Maldraxxus nicht länger.\n\nGut gekämpft, {name}. Kümmern wir uns jetzt um den Wiederaufbau unserer Truppen und die Ordnung im Reich.", sourceObjectiveStatus = "unverified-source-field" }
quests[59021] = { id = 59021, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Läutet ihren Untergang ein", description = "Seit Anbeginn Revendreths war es Temels Aufgabe, die Sünden der Seelen zu verlesen, sodass alle es hören konnten.\n\nJede Seele hier, auch Venthyr, musste diese grimmigen Verkündungen mindestens einmal über sich ergehen lassen.\n\nEr wird wissen, wie man den Sündenstein von Inquisitorin Stelia benutzen muss, um ihre Verteidigung zu durchbrechen.\n\nBefehlt ihm dies einfach, nachdem ihr die Inquisitorin aufgespürt habt, und schaltet sie aus.", sourceObjective = "Befehlt Temel, den Sündenstein von Inquisitorin Stelia zu verlesen, und tötet sie dann.", completion = "Der Zauberschutz auf dem Sündenstein der Anklägerin wurde durch den Tod der Inquisitorin geschwächt.\n\nWir müssen beide Inquisitoren töten, bevor der Schutz endgültig gebrochen ist. Dann haben wir Zugriff auf den Sündenstein der Anklägerin.", sourceObjectiveStatus = "unverified-source-field" }
quests[59023] = { id = 59023, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Tod des Inquisitors", description = "Inquisitor Vilhelm versteckt sich selbstgefällig im hinteren Teil des Hofes und wird von diversen Gargons und loyalen Venthyr beschützt.\n\nWir müssen ihn töten, um den Zauberschutz auf dem Sündenstein der Anklägerin zu brechen, damit ihn der Oberste Kämmerer einsetzen kann.\n\nTemel wird Euch erneut dabei helfen, die Verteidigung des Inquisitors zu durchbrechen. Zögert nicht.", sourceObjective = "Befehlt Temel, den Sündenstein von Inquisitor Vilhelm zu verlesen, und tötet ihn dann.", progress = "Sobald der Inquisitor tot ist, ist der Zauberschutz gebrochen.", completion = "Der Oberste Kämmerer hat seinen Tod bestätigt. Wir sollten uns beeilen.", sourceObjectiveStatus = "unverified-source-field" }
quests[59025] = { id = 59025, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Lich hinters Licht führen", description = "Der Erfolg seines Verrats hat Mor'Bitan selbstgefällig gemacht.\n\nSoll er ihn nur genießen, denn hier endet es für ihn. Wir werden ihn mit diesem Ritual anlocken... und dann werden wir meinen Markgraf rächen.\n\nKämpft an meiner Seite, {name}. Gemeinsam werden wir an diesem Verräter ein Exempel statuieren.", sourceObjective = "Tötet Mor'Bitan.", progress = "Er wird es bereuen, sich mit mir angelegt zu haben.", completion = "Verfluchter Lich, möge seine Seele niemals wiedergeboren werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[59042] = { id = 59042, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein gutes Herz", description = "Ganz gleich, was die meisten glauben, Emeni hat ein gütiges Herz. Ähm... zumindest wird sie eins haben, wenn Ihr es ihr gebt!\n\nIch wüsste niemanden, der besser geeignet wäre als Ihr, <Schlundgänger/Schlundgängerin>, um Emeni ein neues Herz zu geben. Vielleicht kann sie sich dann für Euch erwärmen. Ihr werdet womöglich Freunde oder sogar Seelenbande!\n\nBitte wählt ein Herz aus und platziert es in Emenis Konstrukt.", sourceObjective = "Platziert ein Herz in Emenis Konstrukt.", completion = "Ihr habt es geschafft, das Konstrukt ist fertiggestellt. Die Mördertochter lebt wieder!", sourceObjectiveStatus = "unverified-source-field" }
quests[59043] = { id = 59043, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bäckersdutzend", description = "In genau diesem Zelt bereitete ich Köstlichkeiten zu, die den Halbgöttern Tränen der Freude entlocken würden. Und ich brauche immer Nachschub zum Backen!\n\nDie Mittler verkaufen mir normalerweise Eier von nah und fern, aber vielleicht könntet Ihr mir dieses Mal an ihrer Stelle aushelfen?\n\nSeid Ihr mit den Gorm vertraut? Das sind große Insektenviecher, die im Ardenwald leben. Wenn Ihr mir ein paar ihrer Eier holt, backe ich Euch etwas wirklich Leckeres im Gegenzug!\n\nMama gibt Euch sogar Sülzi zur Unterstützung mit.", sourceObjective = "Reist zum Ardenwald und sammelt 13 schlüpfbereite Gormeier.", completion = "Perfekt! Mama wusste einfach, dass Ihr diese Aufgabe bewältigen könnt!", sourceObjectiveStatus = "unverified-source-field" }
quests[59063] = { id = 59063, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verflucht!", description = "Ach du meine Güte, das ist furchtbar! Einfach nur furchtbar!\n\nIch weiß genau, welch grässlicher Fluch auf dieser armen Seele lastet! Aber diese abscheulichen Spriggans stehlen dauernd meine Schriftrollen, verstreuen sie überall und zerreißen sie!\n\nJetzt strotzen die Wasserfälle nur so vor allerhand gefährlicher Magie!\n\nDie Spriggans haben die Teile der Schriftrolle, die Ihr benötigt. Sammelt sie ein und beschafft einen Einband von einer der großen Verhexungen. Dann solltet ihr alles wieder zusammensetzen können.", sourceObjective = "Sammelt 5 Teile einer zerfetzten Schriftrolle von Fauldornspriggans und einen zerfledderten Einband von einer großen Verhexung, um eine versiegelte Schriftrolle der Seelenfäule zu erschaffen.", progress = "Hmm... Ja, sieht so aus, als ob das hier die richtige ist.", completion = "Ich wusste, dass Dreyden die benötigte Schriftrolle haben würde. Wir dürfen keine Zeit verschwenden!", sourceObjectiveStatus = "unverified-source-field" }
quests[59068] = { id = 59068, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein nie ausgesprochenes Geheimnis", description = "Das erste in der Schriftrolle aufgelistete Reagenz ist ein Geheimnis, das niemals ausgesprochen wurde.\n\nKinderspiel. Ich kenne jemanden mit einem ganzen Haufen Geheimnisse! Behüterin Vesperblüte, unsere Schnüfflerin hier vor Ort. Sie erzählt der Wilden Jagd von allen schändlichen Ereignissen im Wald.\n\nIch bin sicher, sie opfert mit Freuden ein Geheimnis, damit sich Qadarins Seele nicht unter unvorstellbar grausamen Schmerzen einfach ins Nichts auflöst.\n\nIch sage Thiernax, dass er Euch treffen soll, wo auch immer sie sie versteckt hält. Das sollte ihn etwas davon ablenken, was gerade mit seinem Mann geschieht.", sourceObjective = "Besorgt ein nie ausgesprochenes Geheimnis aus den Aufzeichnungen von Behüterin Vesperblüte.", progress = "Puh! Diese Seite... hat Dinge gesehen, die niemand sehen sollte.", completion = "Ihr habt keine Ahnung, wie sehr ich versucht bin, sie zu öffnen und zu lesen. Beeilen wir uns und vollenden den Gegenfluch!", sourceObjectiveStatus = "unverified-source-field" }
quests[59069] = { id = 59069, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Zeichen verlorener Liebe", description = "Meine Schwester Alexstrasza verlor ihren Hauptgefährten Korialstrasz gegen Ende des Krieges mit Todesschwinge.\n\nIn ihrem langen Leben hat sie viele geliebt, aber niemanden so sehr wie ihn. In meinem Herzen weiß ich, dass sie ihn immer noch liebt.\n\nFindet Alexstrasza im Zinnoberrefugium und bittet sie um ein Symbol ihrer verlorenen Liebe. Das wird sich sicherlich als starke Zutat für den Gegenfluch erweisen.", sourceObjective = "Sprecht mit Alexstrasza am Zinnoberrefugium im Schattenhochland.", progress = "Meine Schwester liebt von ganzem Herzen...", completion = "Diese Figur... Ich habe sie nicht mehr gesehen seit...\n\nIch gab sie ihr, als wir zu Aspekten wurden. Unsere Pflichten trennten uns zum ersten Mal in unserem Leben voneinander. Zu wissen, dass sie sie all die Jahre aufgehoben hat...\n\n<Ysera wischt sich die Augen.>\n\nWir werden sie sinnvoll einsetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[59070] = { id = 59070, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Opfer aus Anima", description = "Und als Letztes brauchen wir für diesen Gegenfluch noch etwas eingestimmte Anima.\n\nNatürlich können wir nicht viel entbehren. Deshalb ist dies ein größeres Opfer als es sonst wäre.\n\nAber wisst Ihr was? Die Spriggans haben dieses Chaos angerichtet, also sollen sie beim Aufräumen helfen. Einige wirklich fiese haben in Tirna Scithe Unfug getrieben. Sie sollten die Anima haben, die wir brauchen.\n\nThiernax sieht aus, als würde ihm eine Runde Spriggandreschen so richtig guttun. Ich sorge dafür, dass er sich dort mit Euch trifft.", sourceObjective = "Tötet Spriggans in Tirna Scithe, um befleckte Anima zu sammeln.", progress = "Habt Ihr Euch schon um die Spriggans gekümmert?", completion = "HA! Das haben diese Spriggans nicht besser verdient! Wer sich mit Einhörnern anlegt, kriegt das magische Horn!\n\nJetzt haben wir genug Anima! Und praktischerweise ist er so schon auf die miese Gesinnung des Fluchwirkers eingestimmt.", sourceObjectiveStatus = "unverified-source-field" }
